						cameraAnime.SetCameraAnimationFlip(true);
				}
				else if (trainer != null)
				{
					// shipped: the result of this call is never used (01742a90)
					pViewSystem.SeqComFunc_GetTargetPoke_Org(macro.trg == SEQ_DEF_TRAINER.SEQ_DEF_TRAINER_SEQ_TARGET1 ? 1 : 0);
					Vector3 trainerPos = trainer.GetCalcTranslation();
					if (macro.isLoseCam)
						trainerPos = new Vector3(trainer.GetCalcTranslation().x, trainerPos.y, trainer.GetCalcTranslation().z);

					cameraAnime.SetReserveFollowTrainer(vpos, null, new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f), macro.isLoseCam);
					cameraAnime.SetCameraAnimationOffset(trainerPos + new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f));
					if (macro.isFlip)
						cameraAnime.SetCameraAnimationFlip(true);
					if (macro.isRot)
						cameraAnime.SetCameraAnimationRotateYDeg(trainer.GetRotationVec().y);
				}

				cameraSystem.PlayCameraAnimation(cameraAnime);
			}
		}
