		private void SEQ_CAMERA_FUNC_DEF_CameraNearFarFovSet(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is CameraNearFarFovSet macro)
			{
				SequenceCameraObject camera = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
				float near = macro.near;
				float far = macro.far;
				float fov = macro.fov;
				if (macro.relative)
				{
					near += camera.Near;
					far += camera.Far;
					fov += camera.Fov;
				}

				if (macro.enableElem[CAMERA_SET_NEAR_ELEM])
					camera.Near = near;
				if (macro.enableElem[CAMERA_SET_FAR_ELEM])
					camera.Far = far;
				if (macro.enableElem[CAMERA_SET_FOV_ELEM])
					camera.Fov = fov;
			}
		}
