		private void BTL_SEQ_FUNC_DEF_SetDOFSensorScale(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprSetDOFSensorScale macro)
			{
				int frame = CALC_FRAME(param);
				if (frame == 0)
				{
					SmartPoint.Rendering.DepthOfField.instance.sensorScale = macro.scale;
					return;
				}

				TaskFloatControl task = new TaskFloatControl(SmartPoint.Rendering.DepthOfField.instance.sensorScale, macro.scale, frame, ((EaseFunc)macro.move).GetEase(), x => SmartPoint.Rendering.DepthOfField.instance.sensorScale = x);
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManagerLate().RegisterTask(task, true);
			}
		}
