		private void BTL_SEQ_FUNC_DEF_MessageDispStd(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is MessageDispStd macro && pViewSystem is BattleViewSystem viewSystem)
			{
				if (BattleStr.Instance == null)
					return;

				MessageTextParseDataModel strBuf;
				int msgId = macro.MsgId;
				switch (msgId)
				{
					case BTL_STRID_STD.Encount_Wild1:
					case BTL_STRID_STD.Encount_Wild2:
					case BTL_STRID_STD.Encount_Wild_Move:
					case BTL_STRID_STD.Encount_Wild_Talk:
					case BTL_STRID_STD.Encount_Wild_Ride:
					case BTL_STRID_STD.Encount_Wild_Legend:
					case BTL_STRID_STD.Encount_Band:
					case BTL_STRID_STD.Encount_Nusi:
					case BTL_STRID_STD.Encount_Wild_Mitsu:
					{
						BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_DEF, 0);
						BTL_POKEPARAM bpp = pViewSystem.GetBattlePokeParam(vpos);
						msgId = GetWildEncountMsg(pViewSystem, bpp, msgId);
						if (pViewSystem.GetMainModule().GetSetupStatusFlag(BTL_STATUS_FLAG.BTL_STATUS_TUTORIAL))
							msgId = BTL_STRID_STD.Encount_Wild_Talk;
						strBuf = BattleStr.Instance.MakeStringStd(msgId, new int[] { bpp.GetID() });
						break;
					}
					case BTL_STRID_STD.Encount_NPC1:
					case BTL_STRID_STD.Encount_Player1:
						strBuf = BattleStr.Instance.MakeStringStd(msgId, new int[] { viewSystem.GetEnemyClientID(0) });
						break;
					case BTL_STRID_STD.Encount_NPC2:
					{
						Dpr.Trainer.TrainerType tagType = TrainerSystem.GetTagTrainerType((Dpr.Trainer.TrainerType)viewSystem.GetTrainerType(viewSystem.GetEnemyClientID(0)), (Dpr.Trainer.TrainerType)viewSystem.GetTrainerType(viewSystem.GetEnemyClientID(1)));
						if (tagType != Dpr.Trainer.TrainerType.INVALID)
							strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.Encount_Tag, new int[] { (int)tagType, viewSystem.GetEnemyClientID(0), viewSystem.GetEnemyClientID(1) });
						else
							strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.Encount_NPC2, new int[] { viewSystem.GetEnemyClientID(0), viewSystem.GetEnemyClientID(1) });
						break;
					}
					case BTL_STRID_STD.PutSingle:
					{
						BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK, 0);
						BTL_POKEPARAM bpp = pViewSystem.GetBattlePokeParam(vpos);
						if (pViewSystem.GetMainModule().GetPokeFriendship(bpp) >= MESSAGE_DISP_STD_FRIEND_SHIP_CLOSE_VALUE)
							strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.FR_PutPoke, new int[] { bpp.GetID() });
						else
							strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.PutSingle, new int[] { bpp.GetID() });
						break;
					}
					case BTL_STRID_STD.PutDouble:
					{
						BTL_POKEPARAM bpp1 = pViewSystem.GetBattlePokeParam(BtlvPos.BTL_VPOS_NEAR_1);
						BTL_POKEPARAM bpp2 = pViewSystem.GetBattlePokeParam(BtlvPos.BTL_VPOS_NEAR_2);
						strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.PutDouble, new int[] { bpp1.GetID(), bpp2.GetID() });
						break;
					}
					case BTL_STRID_STD.PutSingle_NPC:
					{
						BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetCharaVPos(SEQ_DEF_TRAINER.SEQ_DEF_TRAINER_SEQ_TARGET1, 0);
						if (macro.option == SEQ_COM_OPTION_MULTI)
							vpos = pViewSystem.SeqComFunc_GetTargetCharaVPos(SEQ_DEF_TRAINER.SEQ_DEF_TRAINER_SEQ_TARGET2, 0);
						BTL_POKEPARAM bpp = pViewSystem.GetBattlePokeParam(vpos);
						strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.PutSingle_NPC, new int[] { viewSystem.GetBtlvPosToClientId(vpos), bpp.GetID() });
						break;
					}
					case BTL_STRID_STD.PutDouble_NPC:
					{
						BtlvPos vpos1 = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK, 0);
						BtlvPos vpos2 = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_DEFTRG, 0);
						BTL_POKEPARAM bpp1 = pViewSystem.GetBattlePokeParam(vpos1);
						BTL_POKEPARAM bpp2 = pViewSystem.GetBattlePokeParam(vpos2);
						strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.PutDouble_NPC, new int[] { viewSystem.GetEnemyClientID(0), bpp1.GetID(), bpp2.GetID() });
						break;
					}
					case BTL_STRID_STD.PutSingle_Player:
					{
						BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK, 0);
						if (macro.option == SEQ_COM_OPTION_MULTI)
							vpos = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_DEFTRG, 0);
						BTL_POKEPARAM bpp = pViewSystem.GetBattlePokeParam(vpos);
						byte clientID = pViewSystem.GetMainModule() != null ? MainModule.PokeIDtoClientID(bpp.GetID()) : (byte)0;
						strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.PutSingle_Player, new int[] { clientID, bpp.GetID() });
						break;
					}
					case BTL_STRID_STD.PutDouble_Player:
					{
						BtlvPos vpos1 = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK, 0);
						BtlvPos vpos2 = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_DEFTRG, 0);
						BTL_POKEPARAM bpp1 = pViewSystem.GetBattlePokeParam(vpos1);
						BTL_POKEPARAM bpp2 = pViewSystem.GetBattlePokeParam(vpos2);
						byte clientID = pViewSystem.GetMainModule() != null ? MainModule.PokeIDtoClientID(bpp1.GetID()) : (byte)0;
						strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.PutDouble_Player, new int[] { clientID, bpp1.GetID(), bpp2.GetID() });
						break;
					}
					case BTL_STRID_STD.WinTrainer:
						// shipped: both arguments are GetEnemyClientID(0) (01745314-01745324)
						strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.WinTrainer, new int[] { viewSystem.GetEnemyClientID(0), viewSystem.GetEnemyClientID(0) });
						break;
					case BTL_STRID_STD.BallThrowS:
					{
						BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_DEF, 0);
						BTL_POKEPARAM bpp = pViewSystem.GetBattlePokeParam(vpos);
						strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.BallThrowS, new int[] { bpp.GetID() });
						break;
					}
					case BTL_STRID_STD.Nusi_DefaultPowerUp_Atk_1:
					case BTL_STRID_STD.DefaultPowerUp_Atk_1:
					{
						// shipped: both case labels build the (non-Nusi) DefaultPowerUp_* message from the enemy's first Pokemon
						DefaultPowerUpDesc desc = viewSystem.GetPartySetupParam(viewSystem.GetEnemyClientID(0)).pokeDesc[0].defaultPowerUpDesc;
						int count = 0;
						int maxRank = 0;
						if (desc.rankUp_Attack != 0)
						{
							count++;
							if (maxRank < desc.rankUp_Attack)
								maxRank = desc.rankUp_Attack;
						}
						if (desc.rankUp_Defense != 0)
						{
							count++;
							if (maxRank < desc.rankUp_Defense)
								maxRank = desc.rankUp_Defense;
						}
						if (desc.rankUp_SpAttack != 0)
						{
							count++;
							if (maxRank < desc.rankUp_SpAttack)
								maxRank = desc.rankUp_SpAttack;
						}
						if (desc.rankUp_SpDefense != 0)
						{
							count++;
							if (maxRank < desc.rankUp_SpDefense)
								maxRank = desc.rankUp_SpDefense;
						}
						if (desc.rankUp_Agility != 0)
						{
							count++;
							if (maxRank < desc.rankUp_Agility)
								maxRank = desc.rankUp_Agility;
						}

						if (count >= 2)
							msgId = BTL_STRID_STD.DefaultPowerUp_All_1 - 1 + maxRank;
						else if (desc.rankUp_Attack != 0)
							msgId = BTL_STRID_STD.DefaultPowerUp_Atk_1 - 1 + desc.rankUp_Attack;
						else if (desc.rankUp_Defense != 0)
							msgId = BTL_STRID_STD.DefaultPowerUp_Def_1 - 1 + desc.rankUp_Defense;
						else if (desc.rankUp_SpAttack != 0)
							msgId = BTL_STRID_STD.DefaultPowerUp_Spatk_1 - 1 + desc.rankUp_SpAttack;
						else if (desc.rankUp_SpDefense != 0)
							msgId = BTL_STRID_STD.DefaultPowerUp_Spdef_1 - 1 + desc.rankUp_SpDefense;
						else if (desc.rankUp_Agility != 0)
							msgId = BTL_STRID_STD.DefaultPowerUp_Agi_1 - 1 + desc.rankUp_Agility;
						else
							msgId = BTL_STRID_STD.DefaultPowerUp_Atk_1;

						BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_DEF, 0);
						BTL_POKEPARAM bpp = pViewSystem.GetBattlePokeParam(vpos);
						strBuf = BattleStr.Instance.MakeStringStd(msgId, new int[] { bpp.GetID() });
						break;
					}
					case BTL_STRID_STD.Encount_Tag:
					{
						Dpr.Trainer.TrainerType tagType = TrainerSystem.GetTagTrainerType((Dpr.Trainer.TrainerType)viewSystem.GetTrainerType(viewSystem.GetEnemyClientID(0)), (Dpr.Trainer.TrainerType)viewSystem.GetTrainerType(viewSystem.GetEnemyClientID(1)));
						strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.Encount_Tag, new int[] { (int)tagType, viewSystem.GetEnemyClientID(0), viewSystem.GetEnemyClientID(1) });
						break;
					}
					case BTL_STRID_STD.RAID_GRights_Get:
						strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.RAID_GRights_Get, new int[] { viewSystem.GetClientID() });
						break;
					case BTL_STRID_STD.RAID_Boss_17:
						strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.RAID_Boss_17, new int[] { viewSystem.GetClientID() });
						break;
					case BTL_STRID_STD.PutMulti_NPC_and_NPC:
					{
						BtlvPos vpos1 = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK, 0);
						BtlvPos vpos2 = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_DEFTRG, 0);
						BTL_POKEPARAM bpp1 = pViewSystem.GetBattlePokeParam(vpos1);
						BTL_POKEPARAM bpp2 = pViewSystem.GetBattlePokeParam(vpos2);
						byte clientID1 = 0;
						byte clientID2 = 0;
						if (pViewSystem.GetMainModule() != null)
						{
							clientID1 = MainModule.PokeIDtoClientID(bpp1.GetID());
							clientID2 = MainModule.PokeIDtoClientID(bpp2.GetID());
						}
						strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.PutMulti_NPC_and_NPC, new int[] { clientID1, bpp1.GetID(), clientID2, bpp2.GetID() });
						break;
					}
					case BTL_STRID_STD.PutMulti_Myself_and_NPC:
					{
						BtlvPos vpos1 = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK, 0);
						BtlvPos vpos2 = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_DEFTRG, 0);
						BTL_POKEPARAM bpp1 = pViewSystem.GetBattlePokeParam(vpos1);
						BTL_POKEPARAM bpp2 = pViewSystem.GetBattlePokeParam(vpos2);
						byte clientID = pViewSystem.GetMainModule() != null ? MainModule.PokeIDtoClientID(bpp2.GetID()) : (byte)0;
						strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.PutMulti_Myself_and_NPC, new int[] { bpp1.GetID(), clientID, bpp2.GetID() });
						break;
					}
					case BTL_STRID_STD.PutMulti_Player_and_Player:
					{
						BtlvPos vpos1 = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK, 0);
						BtlvPos vpos2 = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_DEFTRG, 0);
						BTL_POKEPARAM bpp1 = pViewSystem.GetBattlePokeParam(vpos1);
						BTL_POKEPARAM bpp2 = pViewSystem.GetBattlePokeParam(vpos2);
						byte clientID1 = 0;
						byte clientID2 = 0;
						if (pViewSystem.GetMainModule() != null)
						{
							clientID1 = MainModule.PokeIDtoClientID(bpp1.GetID());
							clientID2 = MainModule.PokeIDtoClientID(bpp2.GetID());
						}
						strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.PutMulti_Player_and_Player, new int[] { clientID1, bpp1.GetID(), clientID2, bpp2.GetID() });
						break;
					}
					case BTL_STRID_STD.PutMulti_Myself_and_Player:
					{
						BtlvPos vpos1 = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK, 0);
						BtlvPos vpos2 = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_DEFTRG, 0);
						BTL_POKEPARAM bpp1 = pViewSystem.GetBattlePokeParam(vpos1);
						BTL_POKEPARAM bpp2 = pViewSystem.GetBattlePokeParam(vpos2);
						byte clientID = pViewSystem.GetMainModule() != null ? MainModule.PokeIDtoClientID(bpp2.GetID()) : (byte)0;
						strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.PutMulti_Myself_and_Player, new int[] { bpp1.GetID(), clientID, bpp2.GetID() });
						break;
					}
					case BTL_STRID_STD.PutMulti_Ally_Player:
					{
						BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK, 0);
						if (macro.option == SEQ_COM_OPTION_MULTI)
							vpos = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_DEFTRG, 0);
						BTL_POKEPARAM bpp = pViewSystem.GetBattlePokeParam(vpos);
						MainModule mainModule = pViewSystem.GetMainModule();
						byte clientID = 0;
						if (mainModule != null)
						{
							clientID = MainModule.PokeIDtoClientID(bpp.GetID());
							if (clientID == mainModule.GetPlayerClientID())
							{
								// the player's own Pokemon: same message as PutSingle (the binary shares that tail, 01746b24)
								if (pViewSystem.GetMainModule().GetPokeFriendship(bpp) >= MESSAGE_DISP_STD_FRIEND_SHIP_CLOSE_VALUE)
									strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.FR_PutPoke, new int[] { bpp.GetID() });
								else
									strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.PutSingle, new int[] { bpp.GetID() });
								break;
							}
						}
						strBuf = BattleStr.Instance.MakeStringStd(BTL_STRID_STD.PutMulti_Ally_Player, new int[] { clientID, bpp.GetID() });
						break;
					}
					case BTL_STRID_STD.Encount_WildDouble:
					case BTL_STRID_STD.Encount_WildDouble_samekind:
					{
						BTL_POKEPARAM bpp1 = pViewSystem.GetBattlePokeParam(BtlvPos.BTL_VPOS_FAR_1);
						BTL_POKEPARAM bpp2 = pViewSystem.GetBattlePokeParam(BtlvPos.BTL_VPOS_FAR_2);
						msgId = bpp1.GetMonsNo() == bpp2.GetMonsNo() ? BTL_STRID_STD.Encount_WildDouble_samekind : BTL_STRID_STD.Encount_WildDouble;
						// shipped: element 0 is never written (0)
						strBuf = BattleStr.Instance.MakeStringStd(msgId, new int[] { 0, bpp1.GetID(), bpp2.GetID() });
						break;
					}
					case BTL_STRID_STD.PutDouble_Tag:
					case BTL_STRID_STD.PutDouble_Tag_samekind:
					{
						Dpr.Trainer.TrainerType tagType = TrainerSystem.GetTagTrainerType((Dpr.Trainer.TrainerType)viewSystem.GetTrainerType(viewSystem.GetEnemyClientID(0)), (Dpr.Trainer.TrainerType)viewSystem.GetTrainerType(viewSystem.GetEnemyClientID(1)));
						BTL_POKEPARAM bpp1 = pViewSystem.GetBattlePokeParam(BtlvPos.BTL_VPOS_FAR_1);
						BTL_POKEPARAM bpp2 = pViewSystem.GetBattlePokeParam(BtlvPos.BTL_VPOS_FAR_2);
						if (tagType == Dpr.Trainer.TrainerType.INVALID)
							goto case BTL_STRID_STD.PutMulti_NPC_and_NPC; // the binary branches into that case's code (01744e74 -> 01744fcc)

						msgId = bpp1.GetMonsNo() == bpp2.GetMonsNo() ? BTL_STRID_STD.PutDouble_Tag_samekind : BTL_STRID_STD.PutDouble_Tag;
						strBuf = BattleStr.Instance.MakeStringStd(msgId, new int[] { (int)tagType, viewSystem.GetEnemyClientID(0), viewSystem.GetEnemyClientID(1), bpp1.GetID(), bpp2.GetID() });
						break;
					}
					default:
					{
						BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK, 0);
						BTL_POKEPARAM bpp = pViewSystem.GetBattlePokeParam(vpos);
						strBuf = BattleStr.Instance.MakeStringStd(msgId, new int[] { bpp.GetID() });
						break;
					}
				}

				viewSystem.GetHUD().MSG_Start(strBuf, false);
				if (macro.autoHide)
				{
					MessageAutoHideTask task = new MessageAutoHideTask(pViewSystem);
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(task, true);
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_MessageDispSet(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is MessageDispSet macro && pViewSystem is BattleViewSystem viewSystem)
			{
				if (BattleStr.Instance == null)
					return;

				BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK, 0);
				BTL_POKEPARAM bpp = pViewSystem.GetBattlePokeParam(vpos);
				int[] args = new int[] { bpp.GetID(), 0 };
				MessageTextParseDataModel strBuf = BattleStr.Instance.MakeStringSet(macro.MsgId, args);
				viewSystem.GetHUD().MSG_Start(strBuf, false);
			}
		}
