		private void BTL_SEQ_FUNC_DEF_SpecialTameVisible(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is SpecialTameVisible macro)
			{
				int num = 1;
				if (macro.trg == SEQ_DEF_POS.SEQ_DEF_POS_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, i);
					if (vpos == BtlvPos.BTL_VPOS_ERROR)
						continue;

					pViewSystem.GetPokeModel(vpos).SetVisibleTame(macro.visible);
				}
			}
		}
