		private void BTL_SEQ_FUNC_DEF_SpecialPokemonRenderVisible(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is SpecialPokemonRenderVisible macro)
			{
				int frame = CALC_FRAME(param);
				int num = 1;
				if (macro.trgPoke == SEQ_DEF_POS.SEQ_DEF_POS_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					BOPokemon pokeModel;
					BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trgPoke, i);
					if (vpos == BtlvPos.BTL_VPOS_ERROR)
						continue;

					pokeModel = pViewSystem.GetPokeModel(vpos);
					pokeModel.SetVisibleShadow(macro.shadow);
					pokeModel.SetVisible(macro.model);
					if (frame > 0 && (!macro.model || !macro.shadow))
					{
						TaskFinishFuncCall task = new TaskFinishFuncCall(frame, () =>
						{
							pokeModel.SetVisibleShadow(true);
							pokeModel.SetVisible(true);
						});
						task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
						pViewSystem.GetTaskManager().RegisterTask(task, true);
					}
				}
			}
		}
