		private void BTL_SEQ_FUNC_DEF_SpecialSetTimeZone(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is SpecialSetTimeZone macro)
			{
				SceneConnector sceneConnector;
				SkyColorSettings skyColorSettings;
				int frame = CALC_FRAME(param);
				sceneConnector = GameManager.connector;
				SEQ_DEF_TIME_ZONE timeZone = macro.timeZone;
				skyColorSettings = SkyColorSettings.global;
				if (macro.timeZone == SEQ_DEF_TIME_ZONE.SEQ_DEF_TIME_ZONE_NONE)
				{
					sceneConnector.ResetLight(false);
					skyColorSettings.ResetSkyColor();
					return;
				}

				sceneConnector.environmentController.SetLight(sceneConnector.renderSettings, (PeriodOfDay)timeZone, 0.0f, 0.0f);
				skyColorSettings.ChangeTemporaryPeriodOfDay((PeriodOfDay)timeZone, 0.0f, null);
				if (frame == 0)
					return;

				TaskFinishFuncCall task = new TaskFinishFuncCall(frame, () =>
				{
					sceneConnector.ResetLight(false);
					skyColorSettings.ResetSkyColor();
				});
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManager().RegisterTask(task, true);
			}
		}
