		private void BTL_SEQ_FUNC_DEF_GaugeDamage(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is GaugeDamage macro && pViewSystem is BattleViewSystem viewSystem)
			{
				int frame = CALC_FRAME(param);
				int interpFrame = frame > 0 ? frame : GAUGE_ANM_DEFAULT_CNT;
				if (macro.trg == SEQ_DEF_POS.SEQ_DEF_POS_DEF)
					pViewSystem.SeqComFunc_GetTargetPokeNum(true); // shipped: the count is never used (0174a06c)

				viewSystem.GetHUD().Apply(interpFrame);
				if (macro.disable)
					return;

				BattleDataTable dataTable = BattleDataTableManager.Instance.BattleDataTable;
				BTLV_WAZA_EFF_PARAM wazaParam = pViewSystem.GetWazaParam();
				uint seId;
				switch (wazaParam.m_damageAbout)
				{
					case Pml.Battle.TypeAffinity.AboutAffinityID.NORMAL:
						seId = AudioManager.Instance.GetIdByName(dataTable.GetBattleConstantString(BattleConstantKey.SEQ_GAUDE_DAMAGE_SE_NORMAL));
						break;
					case Pml.Battle.TypeAffinity.AboutAffinityID.ADVANTAGE:
						seId = AudioManager.Instance.GetIdByName(dataTable.GetBattleConstantString(BattleConstantKey.SEQ_GAUDE_DAMAGE_SE_ADVANTAGE));
						break;
					case Pml.Battle.TypeAffinity.AboutAffinityID.DISADVANTAGE:
						seId = AudioManager.Instance.GetIdByName(dataTable.GetBattleConstantString(BattleConstantKey.SEQ_GAUDE_DAMAGE_SE_DISADVANTAGE));
						break;
					default:
						return;
				}

				if (seId != 0)
				{
					AudioManager.Instance.CreateSe(seId, 0)?.Play(null, false);
					pViewSystem.GetSoundPlayingIDHashTable().Push(new Tuple<int, uint, uint>(param.GroupNo, seId, 0));
				}
			}
		}
