		private void BTL_SEQ_FUNC_DEF_HitBack(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is HitBack macro)
			{
				int num = 1;
				if (macro.trg == SEQ_DEF_POS.SEQ_DEF_POS_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					BOPokemon pokeModel;
					BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, i);
					if (vpos == BtlvPos.BTL_VPOS_ERROR)
						continue;

					pokeModel = pViewSystem.GetPokeModel(vpos);
					if (!(pokeModel != null && pokeModel.IsEnable)) // op_Inequality in the binary (0174a634)
						continue;

					if (macro.isDefault)
					{
						TaskPokeHitBack task = new TaskPokeHitBack(pokeModel, 0, HIT_BACK_BACK_FRAME_CNT);
						task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
						pViewSystem.GetTaskManager().RegisterTask(task, true);
					}
					else
					{
						Vector3 endPos = pokeModel.GetTranslationVec() + -pokeModel.transform.forward * HIT_BACK_LENGTH;
						TaskVectorControl task = new TaskVectorControl(pokeModel.GetTranslationVec(), endPos, EaseFunc.OUT_CUBIC.GetEase(), HIT_BACK_NOT_DEFAULT_CAMERA_BACK_FRAME_CNT, x => pokeModel.SetTranslationVec(x));
#if PC_UNLOCKED_FPS
						task.SetStartTime(param.StartTime).SetEndTime(param.StartTime + 1.0f / PcPlatform.PcFrameClock.LogicRate * HIT_BACK_NOT_DEFAULT_CAMERA_BACK_FRAME_CNT).SetAdvanceMode(Task.AdvanceMode.Time);
#else
						task.SetStartTime(param.StartTime).SetEndTime(param.StartTime + 1.0f / Application.targetFrameRate * HIT_BACK_NOT_DEFAULT_CAMERA_BACK_FRAME_CNT).SetAdvanceMode(Task.AdvanceMode.Time);
#endif
						pViewSystem.GetTaskManager().RegisterTask(task, true);
						pokeModel.HitBackFlg = true;
					}
				}
			}
		}
