		private void BTL_SEQ_FUNC_DEF_DprPokemonUndiscoveredSet(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprPokemonUndiscoveredSet macro && pViewSystem is BattleViewSystem viewSystem)
			{
				int frame = CALC_FRAME(param);
				int num = 1;
				if (macro.trg == SEQ_DEF_POS.SEQ_DEF_POS_DEF)
					num = viewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					BOPokemon pokeModel;
					BtlvPos vpos = viewSystem.SeqComFunc_GetTargetPoke(macro.trg, i);
					if (vpos == BtlvPos.BTL_VPOS_ERROR)
						continue;

					pokeModel = viewSystem.GetPokeModel(vpos);
					if (pokeModel == null)
						continue;

					bool isSee = viewSystem.GetMainModule().IsZukanPokeSeeOnBattleStart(pokeModel.Param.GetMonsNo());
					if (frame == 0)
					{
						pokeModel.Entity.FixMultiplierColor = (Color)(Vector4)macro.endColor;
						continue;
					}

					if (isSee && !macro.isForce)
						continue;

					pokeModel.Entity.FixMultiplierColor = (Color)(Vector4)macro.startColor;
					TaskVectorControl task = new TaskVectorControl(macro.startColor, macro.endColor, ((EaseFunc)macro.move).GetEase(), frame, x => pokeModel.Entity.FixMultiplierColor = (Color)(Vector4)x);
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					viewSystem.GetTaskManager().RegisterTask(task, true);
				}
			}
		}
