		private void BTL_SEQ_FUNC_DEF_DprPokemonRateMotion(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprPokemonRateMotion macro)
			{
				int num = 1;
				if (macro.trg == SEQ_DEF_POS.SEQ_DEF_POS_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, i);
					if (vpos == BtlvPos.BTL_VPOS_ERROR)
						continue;

					BOPokemon pokeModel = pViewSystem.GetPokeModel(vpos);
					if (pViewSystem.GetMainModule().GetSetupStatusFlag(BTL_STATUS_FLAG.BTL_STATUS_TUTORIAL))
					{
						// tail call + return inside the loop (0174bc34): only the first target plays the tutorial motion
						pokeModel.ChangeAnimStatePoke((BattlePokemonEntity.AnimationState)BattleDataTableManager.Instance.BattleDataTable.GetBattleConstantInt(BattleConstantKey.TUTORIAL_BATTLE_ENTRY_MOTION), 0.15f, 0.0f);
						return;
					}

					int state = 0;
					BattleDataTable.SheetPokemonEntryMotionData motionData = BattleDataTableManager.Instance.BattleDataTable.GetPokemonEntryMotionData(macro.index);
					if (motionData != null)
					{
						int rand = UnityEngine.Random.Range(0, 100) + 1;
						int index = 0;
						int total = 0;
						for (int j = 0; j < motionData.rate.Length; j++)
						{
							int min = total + 1;
							total += motionData.rate[j];
							if (min <= rand && rand <= total)
							{
								index = j;
								break;
							}
						}

						if (index < motionData.AnimationState.Length)
							state = motionData.AnimationState[index];
					}

					pokeModel.ChangeAnimStatePoke((BattlePokemonEntity.AnimationState)state, 0.15f, 0.0f);
				}
			}
		}
