		private void BTL_SEQ_FUNC_DEF_DprTrainerScale(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprTrainerScale macro)
			{
				int frame = CALC_FRAME(param);
				int num = 1;
				if (macro.trg == SEQ_DEF_TRAINER_ADD.SEQ_DEF_TRAINER_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					BOTrainer trainer = pViewSystem.SeqComFunc_GetTargetChara(macro.trg, i) as BOTrainer;
					if (trainer == null) // op_Equality (0174ca6c)
						continue;

					Vector3 scale;
					if (macro.relative)
					{
						Vector3 nowScale = trainer.GetScaleVec();
						scale = new Vector3(nowScale.x * macro.scale.x, nowScale.y * macro.scale.y, nowScale.z * macro.scale.z);
					}
					else
					{
						scale = macro.scale;
					}

					if (frame == 0)
					{
						trainer.SetScaleVec(scale);
						continue;
					}

					TaskVectorControl task = new TaskVectorControl(trainer.GetScaleVec(), scale, ((EaseFunc)macro.move).GetEase(), frame, x => trainer.SetScaleVec(x));
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(task, true);
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_DprCameraMovePosition(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprCameraMovePosition macro)
			{
				int frame = CALC_FRAME(param);
				SequenceCameraObject camera = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
				Vector3 pos = new Vector3(macro.pos.x * 0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f);
				if (macro.relative)
					pos = pos + camera.GetPosition();

				Vector3 endPos = camera.GetPosition();
				SetVectorSelectElem(ref endPos, ref pos, macro.enableElemPos);
				if (frame == 0)
				{
					camera.SetPosition(pos); // shipped: the unselected position (0174cf9c)
					return;
				}

				TaskCameraMove task = new TaskCameraMove(camera, endPos, ((EaseFunc)macro.move).GetEase(), frame);
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManagerLate().RegisterTask(task, true);
			}
		}
