		private void BTL_SEQ_FUNC_DEF_DprCameraLookAtPokemon(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprCameraLookAtPokemon macro)
			{
				SequenceCameraObject camera;
				Vector3 targetPos;
				int frame = CALC_FRAME(param);
				camera = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
				BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, 0);
				if (vpos == BtlvPos.BTL_VPOS_ERROR)
					return;

				BOPokemon pokeModel = pViewSystem.GetPokeModel(vpos);
				if (pokeModel == null) // op_Equality (0174d6c4)
					return;

				targetPos = Vector3.zero;
				pokeModel.GetNodePositionSequence(macro.node, ref targetPos);
				Quaternion lookRot = Quaternion.LookRotation(targetPos - camera.GetPosition()); // shipped: the result is never used (0174d794)
				if (frame == 0)
				{
					camera.SetTarget(targetPos);
					return;
				}

				TaskFloatControl task = new TaskFloatControl(frame, ((EaseFunc)macro.move).GetEase(), x => camera.SetTarget(targetPos));
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManagerLate().RegisterTask(task, true);
			}
		}
		private void BTL_SEQ_FUNC_DEF_DprCameraLookAtTrainer(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprCameraLookAtTrainer macro)
			{
				SequenceCameraObject camera;
				Quaternion lookRot;
				Vector3 targetPos;
				int frame = CALC_FRAME(param);
				camera = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
				BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetCharaVPos(macro.trg, 0);
				if (vpos == BtlvPos.BTL_VPOS_ERROR)
					return;

				BOTrainer trainer = pViewSystem.GetTrainerModel(vpos) as BOTrainer;
				if (camera == null) // shipped: op_Equality on the CAMERA, the trainer is never tested (0174dbec)
					return;

				targetPos = Vector3.zero;
				Transform joint = trainer.GetNodeJoint(macro.node);
				if (joint != null) // op_Inequality (0174dc5c)
					targetPos = joint.position;
				else
					targetPos = trainer.GetTranslationVec();

				lookRot = Quaternion.LookRotation(targetPos - camera.GetPosition());
				if (frame == 0)
				{
					camera.SetRotation(Quaternion.Slerp(Quaternion.Euler(camera.GetRotation()), lookRot, 1.0f).eulerAngles);
					return;
				}

				TaskFloatControl task = new TaskFloatControl(frame, ((EaseFunc)macro.move).GetEase(), x =>
				{
					camera.SetRotation(Quaternion.Slerp(Quaternion.Euler(camera.GetRotation()), lookRot, x).eulerAngles);
					camera.SetTarget(targetPos);
				});
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManagerLate().RegisterTask(task, true);
			}
		}
		private void BTL_SEQ_FUNC_DEF_DprCameraLookAtPath(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprCameraLookAtPath macro)
			{
				SequenceCameraObject camera;
				int frame = CALC_FRAME(param);
				camera = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
				Vector3[] points = new Vector3[]
				{
					macro.relative ? camera.GetTarget() + new Vector3(macro.p0.x * 0.01f, macro.p0.y * 0.01f, macro.p0.z * 0.01f) : new Vector3(macro.p0.x * 0.01f, macro.p0.y * 0.01f, macro.p0.z * 0.01f),
					macro.relative ? camera.GetTarget() + new Vector3(macro.p1.x * 0.01f, macro.p1.y * 0.01f, macro.p1.z * 0.01f) : new Vector3(macro.p1.x * 0.01f, macro.p1.y * 0.01f, macro.p1.z * 0.01f),
					macro.relative ? camera.GetTarget() + new Vector3(macro.p2.x * 0.01f, macro.p2.y * 0.01f, macro.p2.z * 0.01f) : new Vector3(macro.p2.x * 0.01f, macro.p2.y * 0.01f, macro.p2.z * 0.01f),
					macro.relative ? camera.GetTarget() + new Vector3(macro.p3.x * 0.01f, macro.p3.y * 0.01f, macro.p3.z * 0.01f) : new Vector3(macro.p3.x * 0.01f, macro.p3.y * 0.01f, macro.p3.z * 0.01f),
				};

				if (frame == 0)
				{
					switch (macro.pathType)
					{
						case SEQ_DEF_PATHTYPE.SEQ_DEF_PATHTYPE_LINE:
							camera.SetTarget(points[1]);
							break;
						case SEQ_DEF_PATHTYPE.SEQ_DEF_PATHTYPE_BEZIER:
							camera.SetTarget(points[3]);
							break;
					}
					return;
				}

				DG.Tweening.Ease ease = ((EaseFunc)macro.move).GetEase();
				TaskFloatControl task;
				switch (macro.pathType)
				{
					case SEQ_DEF_PATHTYPE.SEQ_DEF_PATHTYPE_LINE:
						task = new TaskFloatControl(frame, ease, t =>
						{
							Vector4 from = points[0];
							Vector4 to = points[1];
							Vector3 pos = new Vector4(DG.Tweening.DOVirtual.EasedValue(from.x, to.x, t, ease), DG.Tweening.DOVirtual.EasedValue(from.y, to.y, t, ease),
								DG.Tweening.DOVirtual.EasedValue(from.z, to.z, t, ease), DG.Tweening.DOVirtual.EasedValue(from.w, to.w, t, ease));
							SetVectorSelectElem(ref pos, ref pos, macro.enableElem); // same vector twice: only the bounds checks survive (01c78ab8)
							camera.SetTarget(pos);
						});
						break;
					case SEQ_DEF_PATHTYPE.SEQ_DEF_PATHTYPE_BEZIER:
						task = new TaskFloatControl(frame, ease, t =>
						{
							Vector3 pos = Dpr.Spline.Bezier.CubicBezier(points[0], points[1], points[2], points[3], t);
							SetVectorSelectElem(ref pos, ref pos, macro.enableElem); // same vector twice: only the bounds checks survive (01c788dc)
							camera.SetTarget(pos);
						});
						break;
					default:
						return;
				}

				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManagerLate().RegisterTask(task, true);
			}
		}
		private void BTL_SEQ_FUNC_DEF_DprCameraGroundCheckFlg(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
