		private void BTL_SEQ_FUNC_DEF_DprCameraRotationFreeze(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprCameraRotationFreeze macro)
			{
				SequenceCameraObject camera;
				int frame = CALC_FRAME(param);
				camera = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
				if (camera == null) // op_Equality (0174eb4c)
					return;

				Vector3 rot = macro.relative ? camera.GetRotation() + macro.rot : macro.rot;
				if (!macro.isEnable)
				{
					camera.SetRotationFreeze(false, null);
					return;
				}

				if (macro.isUpdateRot)
					camera.SetRotationFreeze(true, new Vector3?(rot));
				else
					camera.SetRotationFreeze(true, null);

				TaskFinishFuncCall task = new TaskFinishFuncCall(frame, () => camera.SetRotationFreeze(false, null));
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManagerLate().RegisterTask(task, true);
			}
		}
		private void BTL_SEQ_FUNC_DEF_DprCameraMovePositionBezier(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprCameraMovePositionBezier macro)
			{
				int frame = CALC_FRAME(param);
				SequenceCameraObject camera = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
				Vector3[] points = new Vector3[]
				{
					new Vector3(macro.p0.x * 0.01f, macro.p0.y * 0.01f, macro.p0.z * 0.01f),
					new Vector3(macro.p1.x * 0.01f, macro.p1.y * 0.01f, macro.p1.z * 0.01f),
					new Vector3(macro.p2.x * 0.01f, macro.p2.y * 0.01f, macro.p2.z * 0.01f),
					new Vector3(macro.p3.x * 0.01f, macro.p3.y * 0.01f, macro.p3.z * 0.01f),
				};

				if (frame == 0)
				{
					camera.SetPosition(macro.p3); // shipped: the RAW macro value, not the scaled points[3] (0174f128)
					return;
				}

				TaskCameraMoveBezier task = new TaskCameraMoveBezier(camera, macro.relative, points, macro.enableElem, frame, ((EaseFunc)macro.move).GetEase());
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManagerLate().RegisterTask(task, true);
			}
		}
		private void BTL_SEQ_FUNC_DEF_DprCameraMoveRelativeTrainer(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprCameraMoveRelativeTrainer macro)
			{
				int frame = CALC_FRAME(param);
				SequenceCameraObject camera = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
				BOTrainer trainer = pViewSystem.SeqComFunc_GetTargetChara(macro.trgChara, 0) as BOTrainer;
				if (trainer == null) // op_Equality (0174f3d8)
					return;

				Transform joint = trainer.GetNodeJoint(macro.node);
				Vector3 pos = new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f);
				Vector3 trg = new Vector3(macro.trg.x * -0.01f, macro.trg.y * 0.01f, macro.trg.z * 0.01f);
				Vector3 retPos = Vector3.zero;
				Vector3 retTrg = Vector3.zero;
				Vector3 retRot = Vector3.zero; // never used (third Vector3.zero call @0174f4b0, result discarded)
				if (joint == null) // op_Equality (0174f4d8)
					return;

				Vector3 jointPos = joint.position;
				if (macro.isFlip)
				{
					if (pViewSystem.SeqComFunc_IsFlipEffect(pViewSystem.SeqComFunc_GetTargetCharaVPos(macro.trgChara, 0), BtlvPos.BTL_VPOS_ERROR))
					{
						pos.x = -pos.x;
						trg.x = -trg.x;
					}
				}

				if (macro.isRot)
				{
					Mathe.Btlv.RotDegXZ(ref pos, -trainer.transform.rotation.eulerAngles.y);
					Mathe.Btlv.RotDegXZ(ref trg, -trainer.transform.rotation.eulerAngles.y);
				}

				retPos = jointPos + pos;
				retTrg = jointPos + trg;

				Vector3 camPos = camera.GetPosition();
				SetVectorSelectElem(ref camPos, ref retPos, macro.enableElemPos);
				retPos = camPos;
				// shipped quirk (0174f85c-0174f878): the target is selected into a temporary that is never copied back,
				// so enableElemTrg has no effect on the target used below
				Vector3 camTrg = camera.GetTarget();
				SetVectorSelectElem(ref camTrg, ref retTrg, macro.enableElemTrg);

				if (macro.rate != DEFAULT_MOVE_RATE)
				{
					Vector3 nowPos = camera.GetPosition();
					Vector3 nowTrg = camera.GetTarget();
					retPos = nowPos + (retPos - nowPos) * (macro.rate * 0.01f);
					retTrg = nowTrg + (retTrg - nowTrg) * (macro.rate * 0.01f);
				}

				if (frame == 0)
				{
					camera.SetPosition(retPos, retTrg);
					if (macro.fov != 0.0f)
						camera.Fov = macro.fov;
					return;
				}

				TaskCameraMove task = new TaskCameraMove(camera, retPos, retTrg, macro.fov, ((EaseFunc)macro.move).GetEase(), frame);
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManagerLate().RegisterTask(task, true);
			}
		}
		private void BTL_SEQ_FUNC_DEF_DprCameraMoveRelativeModel(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprCameraMoveRelativeModel macro)
			{
				int frame = CALC_FRAME(param);
				SequenceCameraObject camera = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
				if (!_uPtrModelHash.TryGetVector(macro.grpNo, out HashSet<ObjectEntity> models))
					return;

				foreach (ObjectEntity model in models)
				{
					Transform locator = model.GetLocator(macro.nodeIndex);
					if (locator == null) // op_Equality (0174fdb8)
						locator = model.transform;

					Vector3 pos = new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f);
					Vector3 trg = new Vector3(macro.trg.x * -0.01f, macro.trg.y * 0.01f, macro.trg.z * 0.01f);
					Vector3 retPos = Vector3.zero;
					Vector3 retTrg = Vector3.zero;
					Vector3 retRot = Vector3.zero; // never used (third Vector3.zero call @0174fe80, result discarded)
					if (locator == null) // op_Equality (0174feb0)
						return;

					// both arms are the same get_position call in the binary (0174fec0 / 0174fed4)
					Vector3 jointPos = macro.forceUpdate ? locator.position : locator.position;
					if (macro.isFlip)
					{
						if (pViewSystem.SeqComFunc_IsFlipEffect(pViewSystem.SeqComFunc_GetTargetPoke(macro.dirPoke, 0), BtlvPos.BTL_VPOS_ERROR))
						{
							pos.x = -pos.x;
							trg.x = -trg.x;
						}
					}

					if (macro.isRot)
					{
						Mathe.Btlv.RotDegXZ(ref pos, -model.transform.rotation.eulerAngles.y);
						Mathe.Btlv.RotDegXZ(ref trg, -model.transform.rotation.eulerAngles.y);
					}

					retPos = jointPos + pos;
					retTrg = jointPos + trg;

					Vector3 camPos = camera.GetPosition();
					SetVectorSelectElem(ref camPos, ref retPos, macro.enableElemPos);
					retPos = camPos;
					// shipped quirk (01750264-01750280): the target is selected into a temporary that is never copied back
					Vector3 camTrg = camera.GetTarget();
					SetVectorSelectElem(ref camTrg, ref retTrg, macro.enableElemTrg);

					if (macro.rate != DEFAULT_MOVE_RATE)
					{
						Vector3 nowPos = camera.GetPosition();
						Vector3 nowTrg = camera.GetTarget();
						retPos = nowPos + (retPos - nowPos) * (macro.rate * 0.01f);
						retTrg = nowTrg + (retTrg - nowTrg) * (macro.rate * 0.01f);
					}

					if (frame == 0)
					{
						camera.SetPosition(retPos, retTrg);
						if (macro.fov != 0.0f)
							camera.Fov = macro.fov;
						continue;
					}

					TaskCameraMove task = new TaskCameraMove(camera, retPos, retTrg, macro.fov, ((EaseFunc)macro.move).GetEase(), frame);
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManagerLate().RegisterTask(task, true);
				}
			}
		}
		private void SEQ_CAMERA_FUNC_DEF_DprCameraAnimationTrainer(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprCameraAnimationTrainer macro)
			{
				SequenceCameraSystem cameraSystem = GetCameraSystem();
				BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetCharaVPos(macro.trg, 0);
				BOTrainer trainer = pViewSystem.SeqComFunc_GetTargetChara(macro.trg, 0) as BOTrainer;
				Playables.CameraFilePlayable playable = null;
				if (!BattleViewAssetManager.TryGetCameraFilePlayable(macro.camFile, out playable))
					return;

				Playables.CameraFilePlayable cameraAnime = UnityEngine.Object.Instantiate(playable);
				cameraAnime.transform.parent = BattleProc.Instance.Cluster;
				cameraAnime.transform.SetOrigin();
				cameraAnime.SetActive(false);
				if (macro.trg == SEQ_DEF_TRAINER.SEQ_DEF_TRAINER_FIELD_ORIGIN)
				{
					cameraAnime.SetCameraAnimationOffset(Vector3.zero);
					if (macro.isFlip)
						cameraAnime.SetCameraAnimationFlip(true);
				}
				else
				{
					if (trainer == null) // op_Equality (01750b9c): returns without playing the animation
						return;

					// shipped: the result of this call is never used (01750c60)
					pViewSystem.SeqComFunc_GetTargetPoke_Org(macro.trg == SEQ_DEF_TRAINER.SEQ_DEF_TRAINER_SEQ_TARGET1 ? 1 : 0);
					Vector3 trainerPos;
					Transform joint = trainer.GetNodeJoint(macro.node);
					if (joint != null) // op_Inequality (01750c9c)
					{
						trainerPos = joint.position;
					}
					else
					{
						trainerPos = trainer.GetTranslationVec();
						if (macro.isLoseCam)
						{
							trainerPos.x = trainer.GetCalcTranslation().x;
							trainerPos.z = trainer.GetCalcTranslation().z;
						}
					}

					cameraAnime.SetReserveFollowTrainer(vpos, null, new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f), macro.isLoseCam);
					cameraAnime.SetCameraAnimationOffset(trainerPos + new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f));
					if (macro.isFlip)
						cameraAnime.SetCameraAnimationFlip(true);
					if (macro.isRot)
						cameraAnime.SetCameraAnimationRotateYDeg(trainer.GetRotationVec().y);
				}

				cameraSystem.PlayCameraAnimation(cameraAnime);
			}
		}
		private void SEQ_CAMERA_FUNC_DEF_DprCameraAnimation(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprCameraAnimation macro)
