		private void BTL_SEQ_FUNC_DEF_DprParticleMoveRelativeModel(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprParticleMoveRelativeModel macro)
			{
				int frame = CALC_FRAME(param);
				if (!_uPtrParticleVectorHash.TryGetVector(param.GroupNo, out HashSet<BtlvEffectInstance> particles))
					return;
				if (!_uPtrModelHash.TryGetVector(macro.grpNo, out HashSet<ObjectEntity> models))
					return;

				foreach (BtlvEffectInstance particle in particles)
				{
					foreach (ObjectEntity model in models)
					{
						Transform locator = model.GetLocator(macro.nodeIndex);
						if (locator == null) // op_Equality (01751588)
							locator = model.transform;

						if (frame == 0)
						{
							particle.SetTranslationVec(locator.position);
							continue;
						}

						Vector3 pos = locator.position;
						TaskVectorControl task = new TaskVectorControl(particle.GetTranslationVec(), pos, ((EaseFunc)macro.move).GetEase(), frame, x => particle.SetTranslationVec(x));
						task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
						pViewSystem.GetTaskManagerLate().RegisterTask(task, true);
