		private void BTL_SEQ_FUNC_DEF_DprParticleFollowModel(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprParticleFollowModel macro)
			{
				if (!_uPtrParticleVectorHash.TryGetVector(param.GroupNo, out HashSet<BtlvEffectInstance> particles))
					return;

				if (macro.grpNo == RELEASE_GROUP_NO)
				{
					foreach (BtlvEffectInstance particle in particles)
						particle.DetachModel();
					return;
				}

				if (!_uPtrModelHash.TryGetVector(macro.grpNo, out HashSet<ObjectEntity> models))
					return;

				foreach (BtlvEffectInstance particle in particles)
				{
					foreach (ObjectEntity model in models)
					{
						Transform locator = model.GetLocator(macro.nodeIndex);
						if (locator == null) // op_Equality (01751c58)
							locator = model.transform;

						particle.SetTranslationVec(locator.position);
						particle.AttachModel(model, locator, macro.isPos, macro.isRot, macro.isScl, macro.isAnimScl, false);
						particle.SetTranslationOffset(new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f));
						// no Vector3 ctor in the binary (01751cf0): the rotation offset is a copy with y negated
						Vector3 rotOffset = macro.rot;
						rotOffset.y = -rotOffset.y;
						particle.SetRotationVecOffset(rotOffset);
					}
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_DprParticleMultiplyColorSet(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprParticleMultiplyColorSet macro)
			{
				int frame = CALC_FRAME(param);
				if (!_uPtrParticleVectorHash.TryGetVector(param.GroupNo, out HashSet<BtlvEffectInstance> particles))
					return;

				if (macro.reset)
				{
					foreach (BtlvEffectInstance particle in particles)
					{
						if (particle != null) // plain cbz (01752084): BtlvEffectInstance is not a UnityEngine.Object
							particle.SetMultiplyColor(PARTICLE_MULTIPLY_RESET_COLOR);
					}
					return;
				}

				foreach (BtlvEffectInstance particle in particles)
				{
					if (particle == null)
						continue;

					Vector4 color = new Vector4(macro.col.x, macro.col.y, macro.col.z, macro.alpha);
					if (frame == 0)
					{
						particle.SetMultiplyColor(color);
						continue;
					}

					TaskVector4Control task = new TaskVector4Control(particle.Effect.GetMulColor(), color, ((EaseFunc)macro.move).GetEase(), frame, x => particle.SetMultiplyColor(x));
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
