		private void BTL_SEQ_FUNC_DEF_DprParticleCreateSeal(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprParticleCreateSeal macro)
			{
				string path;
				int frame = CALC_FRAME(param);
				path = string.Empty;
				BtlvBallInfo ballInfo = pViewSystem.SeqComFunc_GetEffectBallInfo(macro.index);
				pViewSystem.CheckWazaDataPath_Particle(ref path, macro.index, true, false, false, false);
				if (ballInfo.HasBallSeal)
				{
					BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, 0);
					BOPokemon pokeModel = pViewSystem.GetPokeModel(vpos);
					if (!_uPtrModelHash.TryGetVector(macro.grpNo, out HashSet<ObjectEntity> models))
						return;

					foreach (ObjectEntity model in models)
					{
						BtlvEffectInstance iPtrLightEffect;
						List<BtlvEffectInstance> sealEffects = new List<BtlvEffectInstance>();
						iPtrLightEffect = null;
						bool isContest = false;
						if (pViewSystem is ContestViewSystem)
						{
							ContestPlayerEntity playerEntity = SceneObjectManager.Instance.GetPlayerEntities()[macro.index];
							sealEffects = playerEntity.SealEffects;
							iPtrLightEffect = playerEntity.LightEffect;
							isContest = true;
						}
						else
						{
							model.GetPlaySealEffect(ballInfo.ballId, in ballInfo.affixSealDatas, ref sealEffects, ref iPtrLightEffect);
						}

						if (iPtrLightEffect != null) // plain cbz (01752964)
						{
							// shipped: an existing group is left as it is (no AddVector here, unlike the -9999 group below)
							if (!_uPtrParticleVectorHash.HasVector(param.GroupNo))
								_uPtrParticleVectorHash.CreateVector(param.GroupNo, new HashSet<BtlvEffectInstance> { iPtrLightEffect });

							iPtrLightEffect.Play(x => iPtrLightEffect.Dispose());
							if (frame > 0)
							{
								TaskParticleDelete deleteTask = new TaskParticleDelete(iPtrLightEffect, macro.deleteType, () => _uPtrParticleVectorHash.DeleteVector(param.GroupNo), frame);
								pViewSystem.GetTaskManager().RegisterTask(deleteTask, true);
							}
						}

						if (_uPtrParticleVectorHash.HasVector(-9999))
							_uPtrParticleVectorHash.AddVector(-9999, new HashSet<BtlvEffectInstance>(sealEffects));
						else
							_uPtrParticleVectorHash.CreateVector(-9999, new HashSet<BtlvEffectInstance>(sealEffects));

						TaskSealEffects task = new TaskSealEffects(model, sealEffects, pokeModel.GetAdjustHeight() * Dpr.BallDeco.BallDecoWork.GetEffectPositionOffset(pokeModel.GetSize()), frame, isContest);
						task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
						pViewSystem.GetTaskManager().RegisterTask(task, true);
					}
				}
				else
				{
					VectorHash<int, BtlvEffectInstance> iPtrVec;
					EffectData effectData = BattleViewAssetManager.CachedEffectData.Find(x => x.Item1 == path)?.Item2;
					if (effectData != null)
					{
						iPtrVec = _uPtrParticleVectorHash;
						BtlvEffectInstance iPtrParticle = new BtlvEffectInstance(effectData);
						Vector3 initScale;
						if (iPtrParticle.Effect == null)
							return;

						if (!iPtrVec.HasVector(param.GroupNo))
							iPtrVec.CreateVector(param.GroupNo, new HashSet<BtlvEffectInstance> { iPtrParticle });

						initScale = iPtrParticle.Effect.particleSystem.transform.localScale;
						iPtrParticle.Play(x => iPtrParticle.SetScaleVec(initScale));
						if (frame > 0)
						{
							TaskParticleDelete task = new TaskParticleDelete(iPtrParticle, macro.deleteType, () => iPtrVec.DeleteVector(param.GroupNo), frame);
							task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
							pViewSystem.GetTaskManager().RegisterTask(task, false);
						}
					}
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_DprCutSceneTrainerParticleCreate(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprParticleCreateCutSceneTrainer macro)
			{
				int frame = CALC_FRAME(param);
				int num = 1;
				if (macro.trg == SEQ_DEF_TRAINER.SEQ_DEF_TRAINER_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					string effectName;
					VectorHash<int, BtlvEffectInstance> iPtrVec;
					BtlvEffectInstance iPtrParticle;
					Vector3 initScale;
					BattleViewCharacter trainer = pViewSystem.SeqComFunc_GetTargetChara(macro.trg, i); // shipped: never used (01753598)
					BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetCharaVPos(macro.trg, i);
					if (vpos == BtlvPos.BTL_VPOS_ERROR)
						continue;

					effectName = pViewSystem.GetMainModule().GetClientTrainerEffect((byte)vpos);
					Tuple<string, EffectData> cached = BattleViewAssetManager.CachedEffectData.Find(x => x.Item1 == effectName);
					if (cached == null) // cbz → function exit (01753760): returns, not continue
						return;

					iPtrVec = _uPtrParticleVectorHash;
					iPtrParticle = new BtlvEffectInstance(cached.Item2);
					if (iPtrParticle.Effect == null)
						continue;

					if (!iPtrVec.HasVector(param.GroupNo))
						iPtrVec.CreateVector(param.GroupNo, new HashSet<BtlvEffectInstance> { iPtrParticle });

					initScale = iPtrParticle.Effect.particleSystem.transform.localScale;
					iPtrParticle.Play(x => iPtrParticle.SetScaleVec(initScale));
					if (frame < 1)
						continue;

					TaskParticleDelete task = new TaskParticleDelete(iPtrParticle, macro.deleteType, () => iPtrVec.DeleteVector(param.GroupNo), frame);
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(task, false);
				}
			}
		}
		private void BTL_SWQ_FINC_DEF_DprParticleMoveRelativeTrainer(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
