					TaskVectorControl task = new TaskVectorControl(particle.GetTranslationVec(), jointPos + new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f),
						((EaseFunc)macro.move).GetEase(), frame, x => particle.SetTranslationVec(x));
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(task, true);
