		private void BTL_SWQ_FINC_DEF_DprParticleFollowTrainer(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprParticleFollowTrainer macro)
			{
				if (!_uPtrParticleVectorHash.TryGetVector(param.GroupNo, out HashSet<BtlvEffectInstance> particles))
					return;

				// shipped: the release test is on param.GroupNo (01754168), macro.isEnable and macro.isLocalScl are never read
				if (param.GroupNo == RELEASE_GROUP_NO)
				{
					foreach (BtlvEffectInstance particle in particles)
						particle.DetachModel();
