				}

				foreach (BtlvEffectInstance particle in particles)
				{
					BOTrainer trainer = pViewSystem.SeqComFunc_GetTargetChara(macro.trg, 0) as BOTrainer;
					if (trainer == null) // op_Equality (01754290) → leaves the loop
