						joint = trainer.Entity.GetJoint(JointName.Origin);

					particle.SetTranslationVec(joint.position);
					particle.AttachModel(trainer, joint, macro.isPos, macro.isRot, macro.isScl, macro.isAnimScl, false);
					particle.SetTranslationOffset(new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f));
					// no Vector3 ctor in the binary (01754380): the rotation offset is a copy with y negated
					Vector3 rotOffset = macro.rot;
					rotOffset.y = -rotOffset.y;
					particle.SetRotationVecOffset(rotOffset);
