		}
		private void BTL_SEQ_FUNC_DEF_DprModelAnimationPlayIndex(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprModelAnimationPlayIndex macro)
			{
				int frame = CALC_FRAME(param);
				if (!_uPtrModelHash.TryGetVector(param.GroupNo, out HashSet<ObjectEntity> models))
					return;

				foreach (ObjectEntity model in models)
				{
					ObjectEntity entity;
					if (model == null) // op_Equality (017546ac)
						continue;

					entity = model.GetComponent<ObjectEntity>();
					if (entity == null) // op_Equality (01754704)
						continue;

					entity.Play(macro.index, macro.duration, macro.startTime, macro.isLoop);
					if (frame < 1)
						continue;

					TaskFinishFuncCall task = new TaskFinishFuncCall(frame, () => entity.Stop());
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(task, true);
				}
			}
