		private void BTL_SEQ_FUNC_DEF_DprModelFollowModel(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprModelFollowModel macro)
			{
				if (!_uPtrModelHash.TryGetVector(param.GroupNo, out HashSet<ObjectEntity> models))
					return;

				if (macro.grpNo == RELEASE_GROUP_NO)
				{
					foreach (ObjectEntity model in models)
						model.DetachModel();
					return;
				}

				foreach (ObjectEntity model in models)
				{
					if (!_uPtrModelHash.TryGetVector(macro.grpNo, out HashSet<ObjectEntity> targets))
						continue;

					foreach (ObjectEntity target in targets)
					{
						Transform locator = target.GetLocator(macro.nodeIndex);
						if (locator == null) // op_Equality (01754b14)
							locator = target.transform;

						model.SetTranslationVec(locator.position);
						model.AttachModel(target, locator, macro.isPos, macro.isRot, macro.isScl, false, false);
						model.SetTranslationOffset(macro.pos);
						model.SetRotationVecOffset(macro.rot);
					}
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_DprModelFollowModelMove(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprModelFollowModelMove macro)
			{
