				foreach (ObjectEntity model in models)
				{
					if (!_uPtrModelHash.TryGetVector(macro.grpNo, out HashSet<ObjectEntity> targets))
						continue;

					foreach (ObjectEntity target in targets)
					{
						Transform locator = target.GetLocator(macro.nodeIndex);
						if (locator == null) // op_Equality (01754ffc)
							locator = target.transform;

						if (frame == 0)
						{
							model.SetTranslationVec(locator.position);
							continue;
						}

						Vector3 pos = locator.position;
						TaskVectorControl task = new TaskVectorControl(model.GetTranslationVec(), pos, ((EaseFunc)macro.move).GetEase(), frame, x => model.SetTranslationVec(x));
						task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
						pViewSystem.GetTaskManagerLate().RegisterTask(task, true);
					}
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_DprModelAttachTrainer(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DprModelAttachTrainer macro)
			{
				if (!_uPtrModelHash.TryGetVector(param.GroupNo, out HashSet<ObjectEntity> models))
