					// shipped: macro.changeLight is never read
					if (macro.isEnable)
						trainer.AttachObject(model, (JointName)macro.node, macro.ignoreDominantHand, macro.enableDominantHoldBallHand, true, true, true, macro.isAnimScl, macro.isLocalScl);
					else
						trainer.DetachObject(model);
