		private void BTL_SEQ_FUNC_DEF_SoundPostEvent(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is SoundPostEvent macro)
			{
				string eventName = macro.@event;
				if (pViewSystem is BattleViewSystem viewSystem && macro.isAttrEffect)
					eventName = viewSystem.GetSoundEventName();

				if (string.IsNullOrEmpty(eventName))
					return;

				uint seId = AudioManager.Instance.GetIdByName(eventName);
				SequenceCameraObject camera = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
				AudioInstance audioInstance = AudioManager.Instance.CreateSe(seId, 0, camera.transform.position, camera.transform.rotation, null);
				if (audioInstance == null) // plain cbz (017560b4): AudioInstance is not a UnityEngine.Object
					return;

				audioInstance.Play(null, false);
				if (seId != 0)
					pViewSystem.GetSoundPlayingIDHashTable().Push(new Tuple<int, uint, uint>(param.GroupNo, seId, 0));
			}
		}
