				int frame = CALC_FRAME(param);
				if (frame == 0)
					return;

				viewSystem.SetReqCheckPinch(macro.isRTPC);
				viewSystem.SetCanChangePinch(macro.isPlay);
				if (frame < 1)
					return;

				TaskFinishFuncCall task = new TaskFinishFuncCall(frame, () =>
				{
					viewSystem.SetReqCheckPinch(true);
					viewSystem.SetCanChangePinch(true);
				});
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManager().RegisterTask(task, true);
			}
		}
