		private void BTL_SEQ_FUNC_DEF_Sound3DMovePosition(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is Sound3DMovePosition macro)
			{
				int frame = CALC_FRAME(param);
				if (!_uPtrSoundHash.TryGetVector(param.GroupNo, out HashSet<BtlvSound> sounds) || sounds == null)
					return;

				foreach (BtlvSound sound in sounds)
				{
					Vector3 pos = new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f);
					if (macro.relative)
						pos = pos + sound.GetTranslationVec();

					Vector3 endPos = sound.GetTranslationVec();
					SetVectorSelectElem(ref endPos, ref pos, macro.enableElem);
					if (frame == 0)
					{
						sound.SetTranslationVec(endPos);
						continue;
					}

					TaskVectorControl task = new TaskVectorControl(sound.GetTranslationVec(), endPos, ((EaseFunc)macro.move).GetEase(), frame, x => sound.SetTranslationVec(x));
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(task, true);
				}
			}
		}
