		private void BTL_SEQ_FUNC_DEF_Sound3DFollowModel(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is Sound3DFollowModel macro)
			{
				if (!_uPtrSoundHash.TryGetVector(param.GroupNo, out HashSet<BtlvSound> sounds))
					return;

				switch (macro.type)
				{
					case SEQ_DEF_FOLLOW.SEQ_DEF_FOLLOW_PARTICLE:
						if (macro.grpNo == RELEASE_GROUP_NO)
						{
							foreach (BtlvSound sound in sounds)
								sound.DetachModel();
							return;
						}

						foreach (BtlvSound sound in sounds)
						{
							if (!_uPtrParticleVectorHash.TryGetVector(macro.grpNo, out HashSet<BtlvEffectInstance> particles))
								continue;

							foreach (BtlvEffectInstance particle in particles)
							{
								sound.AttachModel(particle, particle.Effect.gameObject.transform, macro.isPos, macro.isRot, macro.isScl, false, false);
								sound.SetTranslationOffset(new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f));
								// no Vector3 ctor in the binary (017578ec): the rotation offset is a copy with y negated
								Vector3 rotOffset = macro.rot;
								rotOffset.y = -rotOffset.y;
								sound.SetRotationVecOffset(rotOffset);
							}
						}
						break;

					case SEQ_DEF_FOLLOW.SEQ_DEF_FOLLOW_MODEL:
						if (macro.grpNo == RELEASE_GROUP_NO)
						{
							foreach (BtlvSound sound in sounds)
								sound.DetachModel();
							return;
						}

						foreach (BtlvSound sound in sounds)
						{
							if (!_uPtrModelHash.TryGetVector(macro.grpNo, out HashSet<ObjectEntity> models))
								continue;

							foreach (ObjectEntity model in models)
							{
								Transform locator = model.GetLocator(0);
								if (macro.node != string.Empty)
									locator = model.GetLocatorByName(macro.node);

								sound.AttachModel(model, locator, macro.isPos, macro.isRot, macro.isScl, false, false);
								sound.SetTranslationOffset(new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f));
								// no Vector3 ctor in the binary (01757b3c): the rotation offset is a copy with y negated
								Vector3 rotOffset = macro.rot;
								rotOffset.y = -rotOffset.y;
								sound.SetRotationVecOffset(rotOffset);
							}
						}
						break;
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_Sound3DFollowPoke(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is Sound3DFollowPoke macro)
			{
				if (!_uPtrSoundHash.TryGetVector(param.GroupNo, out HashSet<BtlvSound> sounds))
					return;

				if (macro.isEnable)
				{
					int index = 0;
					foreach (BtlvSound sound in sounds)
					{
						BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.pos, index);
						if (vpos == BtlvPos.BTL_VPOS_ERROR)
							continue;

						BOPokemon pokeModel = pViewSystem.GetPokeModel(vpos);
						if (pokeModel == null) // op_Equality (01758130)
							continue;

						sound.AttachPoke(pokeModel, macro.node, macro.isRot, macro.isScl, false);
						sound.SetTranslationOffset(new Vector3(macro.posOfs.x * -0.01f, macro.posOfs.y * 0.01f, macro.posOfs.z * 0.01f));
						index++; // only after a successful attach (01758194)
					}
				}
				else
				{
					foreach (BtlvSound sound in sounds)
					{
						if (sound != null) // plain cbz (017581f0)
							sound.DetachPoke();
					}
				}
			}
		}
