		private void BTL_SEQ_FUNC_DEF_Sound3DPlayVoice(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is Sound3DPlayVoice macro)
			{
				if (macro.is2DSound)
				{
					int num = 1;
					if (macro.trg == SEQ_DEF_POS.SEQ_DEF_POS_DEF)
						num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

					for (int i = 0; i < num; i++)
					{
						BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, i);
						if (vpos == BtlvPos.BTL_VPOS_ERROR)
							continue;

						BOPokemon pokeModel = pViewSystem.GetPokeModel(vpos);
						if (pokeModel == null) // op_Equality (01758884)
							continue;

						SimpleParam simpleParam = pokeModel.Entity.GetSimpleParam();
						string eventName = string.Format(WWISE_PLAY_VOICE_EV, (int)simpleParam.monsNo, simpleParam.formNo, macro.voiceType);
						uint voiceId = AudioManager.Instance.GetIdByName(eventName);
						AudioManager.Instance.CreateVoice(voiceId)?.Play(null, false);
					}
					return;
				}

				if (!_uPtrSoundHash.TryGetVector(param.GroupNo, out HashSet<BtlvSound> sounds))
					return;

				int index = 0;
				foreach (BtlvSound sound in sounds)
				{
					if (sound == null) // plain cbz (017584b8)
						continue;

					BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, index);
					if (vpos == BtlvPos.BTL_VPOS_ERROR)
						continue;

					BOPokemon pokeModel = pViewSystem.GetPokeModel(vpos);
					if (pokeModel == null) // op_Equality (017585b8)
						continue;

					SimpleParam simpleParam = pokeModel.Entity.GetSimpleParam();
					string eventName = string.Format(WWISE_PLAY_VOICE_BTL, (int)simpleParam.monsNo, simpleParam.formNo, macro.voiceType);
					BTL_POKEPARAM bpp = pViewSystem.GetBattlePokeParam(vpos);
					bool isDead = bpp != null && bpp.IsDead();
					float rtpcValue = 1.0f;
					if (macro.IsPinch)
						rtpcValue = (isDead || pokeModel.GetRTPC_IsPlayPinchSound()) ? 0.0f : 1.0f;

					sound.SetRTPC(3252471053u, rtpcValue, 0); // Wwise RTPC id 0xc1dc050d (no named constant in AK.GAME_PARAMETERS)
					sound.SetVoiceFlag();
					sound.PostEvent(eventName, null);
					index++;
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_Sound3DPlayPokeVoice(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is Sound3DPlayPokeVoice macro)
			{
				if (!_uPtrSoundHash.TryGetVector(param.GroupNo, out HashSet<BtlvSound> sounds))
					return;

				int index = 0;
				foreach (BtlvSound sound in sounds)
				{
					BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, index);
					if (vpos == BtlvPos.BTL_VPOS_ERROR)
						continue;

					BOPokemon pokeModel = pViewSystem.GetPokeModel(vpos);
					if (pokeModel == null) // op_Equality (01758c70)
						continue;

					BTL_POKEPARAM bpp = pViewSystem.GetBattlePokeParam(vpos);
					bool isDead = bpp != null && bpp.IsDead();
					float rtpcValue = 1.0f;
					if (macro.IsPinch)
						rtpcValue = (isDead || pokeModel.GetRTPC_IsPlayPinchSound()) ? 0.0f : 1.0f;

					sound.SetRTPC(3252471053u, rtpcValue, 0); // Wwise RTPC id 0xc1dc050d (no named constant in AK.GAME_PARAMETERS)
					PokeVoiceParameter voiceParam = pokeModel.GetPokeVoiceParams(macro.voiceName, macro.playType);
					if (voiceParam.isSetSwitch)
						sound.SetSwitch(voiceParam.SwitchGroup, voiceParam.SwitchName);

					sound.SetVoiceFlag();
					sound.PostEvent(voiceParam.PostEventName, null);
					index++;
				}
			}
		}
