		private void BTL_SEQ_FUNC_DEF_DispEffectSpBackgroundTranslate(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DispEffectSpBackgroundTranslate macro)
			{
				Transform holder;
				int frame = CALC_FRAME(param);
				holder = GameManager.battleObjectHolder;
				if (macro.isReset)
				{
					holder.position = BACKGROUND_DEFAULT_POSITION;
					holder.rotation = Quaternion.Euler(BACKGROUND_DEFAULT_ROTATION);
					holder.localScale = BACKGROUND_DEFAULT_SCALE;
					return;
				}

				Vector3 position = new Vector3(macro.position.x * 0.01f, macro.position.y * 0.01f, macro.position.z * 0.01f);
				Vector3 rotation = macro.rotation;
				Vector3 scale = macro.scale;
				if (frame == 0)
				{
					holder.position = position;
					holder.rotation = Quaternion.Euler(rotation);
					holder.localScale = scale;
					return;
				}

				DG.Tweening.Ease ease = ((EaseFunc)macro.move).GetEase();
				TaskVectorControl positionTask = new TaskVectorControl(holder.position, position, ease, frame, x => holder.position = x);
				positionTask.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				TaskVectorControl rotationTask = new TaskVectorControl(holder.rotation.eulerAngles, rotation, ease, frame, x => holder.rotation = Quaternion.Euler(x));
				rotationTask.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				TaskVectorControl scaleTask = new TaskVectorControl(holder.localScale, scale, ease, frame, x => holder.localScale = x);
				scaleTask.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManager().RegisterTask(positionTask, true);
				pViewSystem.GetTaskManager().RegisterTask(rotationTask, true);
				pViewSystem.GetTaskManager().RegisterTask(scaleTask, true);
			}
		}
		private void BTL_SEQ_FUNC_DEF_DispEffectDispBackGroundTrg(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DispEffectDispBackGroundTrg macro)
			{
				BattleFieldObject fieldObject = BattleConnector.BattleFieldObject;
				if (fieldObject == null) // op_Equality (01759a90)
					return;

				GameObject[] objects = null;
				switch (macro.trg)
				{
					case SEQ_DEF_BACKGROUND_TRG.SEQ_DEF_BACKGROUND_TRG_CEILING:
						objects = fieldObject.CeilingObjects;
						break;
				}

				if (ExtensionMethods.IsNullOrEmpty(objects))
					return;
				if (!ExtensionMethods.IsBounds(objects, macro.index))
					return;

				GameObject target = objects[macro.index];
				if (target == null) // op_Equality (01759b1c)
					return;

				target.SetActive(macro.isDisp);
			}
		}
		private void BTL_SEQ_FUNC_DEF_DispEffectDispBackGroundAll(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DispEffectDispBackGroundAll macro)
			{
				BattleFieldObject fieldObject = BattleConnector.BattleFieldObject;
				if (fieldObject == null) // op_Equality (01759c70)
					return;

				GameObject[] objects = null;
				switch (macro.trg)
				{
					case SEQ_DEF_BACKGROUND_TRG.SEQ_DEF_BACKGROUND_TRG_CEILING:
						objects = fieldObject.CeilingObjects;
						break;
				}

				if (ExtensionMethods.IsNullOrEmpty(objects))
					return;

				for (int i = 0; i < objects.Length; i++)
					objects[i].SetActive(macro.isDisp);
			}
		}
		private void BTL_SEQ_FUNC_DEF_DispEffectSpEnvironmentLightDir(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DispEffectSpEnvironmentLightDir macro)
			{
				EnvironmentController environment = EnvironmentController.global;
				if (environment == null) // op_Equality (01759e74)
					return;

				int frame = CALC_FRAME(param);
				if (macro.isReset)
				{
					environment.parameters.PitchYaw = _environmentParam.PitchYaw;
					return;
				}

				if (frame == 0)
				{
					environment.parameters.PitchYaw = new Vector2(macro.pitch, macro.yaw);
					return;
				}

				TaskVectorControl task = new TaskVectorControl(environment.parameters.PitchYaw, new Vector2(macro.pitch, macro.yaw), ((EaseFunc)macro.move).GetEase(), frame, x => environment.parameters.PitchYaw = x);
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManager().RegisterTask(task, true);
			}
		}
		private void BTL_SEQ_FUNC_DEF_DispEffectSpEnvironmentCharacterColorSet(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DispEffectSpEnvironmentCharacterColorSet macro)
			{
				EnvironmentController environment = EnvironmentController.global;
				if (environment == null) // op_Equality (0175a240)
					return;

				int frame = CALC_FRAME(param);
				if (macro.isReset)
				{
					environment.parameters.CharacterLightColor = _environmentParam.CharacterLightColor;
					environment.parameters.CharacterLightIntensity = _environmentParam.CharacterLightIntensity;
					environment.parameters.CharacterReflectorColor = _environmentParam.CharacterReflectorColor;
					return;
				}

				if (frame == 0)
				{
					environment.parameters.CharacterLightColor = (Vector4)macro.characterLightColor;
					environment.parameters.CharacterLightIntensity = macro.characterLightIntensity;
					environment.parameters.CharacterReflectorColor = (Vector4)macro.characterReflectorColor;
					return;
				}

				Vector4 lightColorFrom = environment.parameters.CharacterLightColor;
				Vector4 lightColorTo = macro.characterLightColor;
				float intensityFrom = environment.parameters.CharacterLightIntensity;
				float intensityTo = macro.characterLightIntensity;
				Vector4 reflectorColorFrom = environment.parameters.CharacterReflectorColor;
				Vector4 reflectorColorTo = macro.characterReflectorColor;
				TaskFloatControl task = new TaskFloatControl(frame, ((EaseFunc)macro.move).GetEase(), t =>
				{
					environment.parameters.CharacterLightColor = Vector4.Lerp(lightColorFrom, lightColorTo, t);
					environment.parameters.CharacterLightIntensity = Mathf.Lerp(intensityFrom, intensityTo, t);
					environment.parameters.CharacterReflectorColor = Vector4.Lerp(reflectorColorFrom, reflectorColorTo, t);
				});
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManager().RegisterTask(task, true);
			}
		}
		private void BTL_SEQ_FUNC_DEF_DispEffectSpEnvironmentPokemonColorSet(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is DispEffectSpEnvironmentPokemonColorSet macro)
			{
				EnvironmentController controller = EnvironmentController.global;
				if (controller == null)
					return;

				int frame = CALC_FRAME(param);
				if (macro.isReset)
				{
					controller.parameters.PokeLightColor = _environmentParam.PokeLightColor;
					controller.parameters.PokeLightIntensity = _environmentParam.PokeLightIntensity;
					controller.parameters.PokeReflectorColor = _environmentParam.PokeReflectorColor;
				}
				else if (frame != 0)
				{
					FromToPair<Vector4> pokeLightColor = new FromToPair<Vector4>(controller.parameters.PokeLightColor, macro.pokeLightColor);
					FromToPair<float> pokeLightIntensity = new FromToPair<float>(controller.parameters.PokeLightIntensity, macro.pokeLightIntensity);
					FromToPair<Vector4> pokeReflectorColor = new FromToPair<Vector4>(controller.parameters.PokeReflectorColor, macro.pokeReflectorColor);
					TaskFloatControl task = new TaskFloatControl(frame, ((EaseFunc)macro.move).GetEase(), x =>
					{
						controller.parameters.PokeLightColor = Vector4.Lerp(pokeLightColor.from, pokeLightColor.to, x);
						controller.parameters.PokeLightIntensity = Mathf.Lerp(pokeLightIntensity.from, pokeLightIntensity.to, x);
						controller.parameters.PokeReflectorColor = Vector4.Lerp(pokeReflectorColor.from, pokeReflectorColor.to, x);
					});
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(task, true);
				}
				else
				{
					controller.parameters.PokeLightColor = (Vector4)macro.pokeLightColor;
					controller.parameters.PokeLightIntensity = macro.pokeLightIntensity;
					controller.parameters.PokeReflectorColor = (Vector4)macro.pokeReflectorColor;
				}
			}
		}
