		private void BTL_SEQ_FUNC_DEF_UniQualitySettingsShadow(global::Dpr.SequenceEditor.SequenceFile pSequenceFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (!(param.Macro is UniQualitySettingsShadow macro))
				return;

			if (EnvironmentController.global == null)
				return;

			int frame = CALC_FRAME(param);
			if (macro.isReset)
			{
				EnvironmentController.global.ResetShadowSettings();
				return;
			}

			if (frame != 0)
			{
				float shadowDistance = EnvironmentController.global._ShadowDistance;
				float shadowNearPlaneOffset = EnvironmentController.global._ShadowNearPlaneOffset;
				TaskFloatControl task = new TaskFloatControl(frame, DG.Tweening.Ease.Linear, x =>
				{
					EnvironmentController.global._ShadowDistance = Mathf.Lerp(shadowDistance, macro.shadowDistance, x);
					// Shipped quirk (01c795c0): the near-plane offset lerps towards macro.shadowDistance, not shadowNearPlaneOffset.
					EnvironmentController.global._ShadowNearPlaneOffset = Mathf.Lerp(shadowNearPlaneOffset, macro.shadowDistance, x);
				});
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManager().RegisterTask(task, true);
				return;
			}

			EnvironmentController.global._ShadowDistance = macro.shadowDistance;
			EnvironmentController.global._ShadowNearPlaneOffset = macro.shadowNearPlaneOffset;
		}
