		private void BTL_SEQ_FUNC_DEF_EffSpBackColFlg(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is EffSpBackColFlg macro && pViewSystem is BattleViewSystem)
			{
				int frame = CALC_FRAME(param);
				SequenceCameraObject iPtrBtlvCameraSystem = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
				if (iPtrBtlvCameraSystem == null)
					return;

				PfxParam pfxParam = iPtrBtlvCameraSystem.GetPostEffects().GetPfxParam();
				pfxParam.isColorFilterEnabled = macro.visible;
				if (macro.visible)
				{
					if (frame > 0)
					{
						TaskFinishFuncCall task = new TaskFinishFuncCall(frame, () =>
						{
							pfxParam = iPtrBtlvCameraSystem.GetPostEffects().GetPfxParam();
							pfxParam.isColorFilterEnabled = false;
							iPtrBtlvCameraSystem.GetPostEffects().SetPfxParam(pfxParam, true);
						});
						task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
						pViewSystem.GetTaskManagerLate().RegisterTask(task, true);
					}

					pfxParam.colorFilterR = macro.col.x;
					pfxParam.colorFilterG = macro.col.y;
					pfxParam.colorFilterB = macro.col.z;
					pfxParam.colorFilterA = macro.alpha;
				}
				else
				{
					pfxParam.SetDefaultColorFilter();
				}

				iPtrBtlvCameraSystem.GetPostEffects().SetPfxParam(pfxParam, true);
			}
		}
		private void BTL_SEQ_FUNC_DEF_EffSpBackColSet(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is EffSpBackColSet macro)
			{
				int frame = CALC_FRAME(param);
				SequenceCameraObject iPtrBtlvCameraSystem = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
				if (iPtrBtlvCameraSystem == null)
					return;

				PfxParam pfxParam = iPtrBtlvCameraSystem.GetPostEffects().GetPfxParam();
				Vector4 start = new Vector4(pfxParam.colorFilterR, pfxParam.colorFilterG, pfxParam.colorFilterB, pfxParam.colorFilterA);
				Vector4 end = new Vector4(macro.col.x, macro.col.y, macro.col.z, macro.alpha);
				if (frame != 0)
				{
					TaskVector4Control task = new TaskVector4Control(start, end, DG.Tweening.Ease.Linear, frame, x =>
					{
						pfxParam = iPtrBtlvCameraSystem.GetPostEffects().GetPfxParam();
						pfxParam.colorFilterR = x.x;
						pfxParam.colorFilterG = x.y;
						pfxParam.colorFilterB = x.z;
						pfxParam.colorFilterA = x.w;
						iPtrBtlvCameraSystem.GetPostEffects().SetPfxParam(pfxParam, true);
					});
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManagerLate().RegisterTask(task, true);
					return;
				}

				pfxParam.colorFilterR = end.x;
				pfxParam.colorFilterG = end.y;
				pfxParam.colorFilterB = end.z;
				pfxParam.colorFilterA = end.w;
				iPtrBtlvCameraSystem.GetPostEffects().SetPfxParam(pfxParam, true);
			}
		}
