			if (param.Macro is EffSpFadeIn macro)
			{
				int frame = CALC_FRAME(param);
				SmartPoint.Components.Fader.fadeMode = SmartPoint.Components.Fader.FadeMode.Color;
				SmartPoint.Components.Fader.fillColor = new Color32((byte)macro.col.x, (byte)macro.col.y, (byte)macro.col.z, (byte)macro.alpha);
				if (frame == 0)
					frame = FADE_DEFAULT_SYNC;

