		private void BTL_SEQ_FUNC_DEF_EffFeedbackEffectSet(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is EffFeedbackEffectSet macro)
			{
				int frame = CALC_FRAME(param);
				SequenceCameraObject iPtrBtlvCameraSystem = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
				if (iPtrBtlvCameraSystem == null)
					return;

				if (frame != 0)
				{
					TaskFeedBackEffectControl task = new TaskFeedBackEffectControl(iPtrBtlvCameraSystem, macro.weight, macro.Rotation, macro.Scale, macro.Hue, macro.Saturation, macro.Brightness, macro.Contrast, ((EaseFunc)macro.move).GetEase(), frame);
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManagerLate().RegisterTask(task, true);
				}
				else
				{
					PfxParam pfxParam = iPtrBtlvCameraSystem.GetPostEffects().GetPfxParam();
