		private void BTL_SEQ_FUNC_DEF_ModelCreate(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ModelCreate value)
			{
				ObjectEntity model;
				int frame = CALC_FRAME(param);
				Tuple<string, ObjectEntity> cached = BattleViewAssetManager.CachedModelData.Find(x => x.Item1 == value.file);
				if (cached == null)
					return;

				if (cached.Item2 == null)
					return;

				model = UnityEngine.Object.Instantiate(cached.Item2);
				if (!_uPtrModelHash.HasVector(param.GroupNo))
				{
					HashSet<ObjectEntity> models = new HashSet<ObjectEntity>();
					models.Add(model);
					_uPtrModelHash.CreateVector(param.GroupNo, models);
				}

				bool isStencilEnable = pViewSystem.IsStencilEnable; // read and discarded in the binary (0175e458)
				int num = 1;
				if (value.isMulti)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					if (frame > 0)
					{
						model.SetActive(true);
						TaskModelDelete task = new TaskModelDelete(model.gameObject, () =>
						{
							_uPtrModelHash.DeleteVector(param.GroupNo);
							UnityEngine.Object.Destroy(model.gameObject);
						}, frame);
						task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
						pViewSystem.GetTaskManager().RegisterTask(task, false);
					}
				}
			}
		}
