		private void BTL_SEQ_FUNC_DEF_ModelFollowModel(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ModelFollowModel macro)
			{
				int frame = CALC_FRAME(param); // unused: only its class-init test survives (0176172c)
				if (_uPtrModelHash.TryGetVector(param.GroupNo, out HashSet<ObjectEntity> models))
				{
					if (macro.grpNo != -1)
					{
						foreach (ObjectEntity iPtrObj in models)
						{
							if (_uPtrModelHash.TryGetVector(macro.grpNo, out HashSet<ObjectEntity> parents))
							{
								foreach (ObjectEntity parent in parents)
								{
									Transform joint = parent.GetLocatorByName(macro.node);
									if (joint == null)
										joint = parent.transform;

									iPtrObj.SetTranslationVec(joint.position);
									iPtrObj.AttachModel(parent, joint, macro.isPos, macro.isRot, macro.isScl, false, false);
									iPtrObj.SetTranslationOffset(macro.pos);
									iPtrObj.SetRotationVecOffset(macro.rot);
								}
							}
						}
					}
					else
					{
						foreach (ObjectEntity iPtrObj in models)
							iPtrObj.DetachModel();
					}
				}
			}
		}
