		private void BTL_SEQ_FUNC_DEF_ParticleCreate(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ParticleCreate macro)
			{
				int frame = CALC_FRAME(param);
				string path = macro.file;
				pViewSystem.CheckWazaDataPath_Particle(ref path, macro.index, macro.isBallEffect, macro.isCapture, macro.isAttrEffect, macro.isStreamLineEffect);
				Tuple<string, EffectData> cached = BattleViewAssetManager.CachedEffectData.Find(x => x.Item1 == path);
				if (cached == null)
					return;

				EffectData effectData = cached.Item2;
				if (effectData == null)
					return;

				Camera camera = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main).Camera; // result unused in the binary (01762838)
				VectorHash<int, BtlvEffectInstance> iPtrVec = _uPtrParticleVectorHash;
				if (macro.isMulti)
				{
					HashSet<BtlvEffectInstance> particles = new HashSet<BtlvEffectInstance>();
					for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
					{
						BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_DEF, i);
						if (vpos == BtlvPos.BTL_VPOS_ERROR)
							continue;

						BtlvEffectInstance iPtrParticle = new BtlvEffectInstance(effectData, macro.drawType);
						if (iPtrParticle.Effect == null)
							continue;

						if (pViewSystem.GetPokeModel(vpos) == null)
							continue;

						if (!iPtrVec.HasVector(param.GroupNo))
							particles.Add(iPtrParticle);

						Vector3 initScale = iPtrParticle.Effect.particleSystem.transform.localScale;
						iPtrParticle.Play(x => iPtrParticle.SetScaleVec(initScale));
						if (frame > 0)
						{
							TaskParticleDelete task = new TaskParticleDelete(iPtrParticle, macro.deleteType, () => iPtrVec.DeleteVector(param.GroupNo), frame, 0);
							task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
							pViewSystem.GetTaskManager().RegisterTask(task, false);
						}
					}

					iPtrVec.CreateVector(param.GroupNo, particles);
				}
				else
				{
					BtlvEffectInstance iPtrParticle = new BtlvEffectInstance(effectData, macro.drawType);
					if (pViewSystem is BattleViewSystem battleViewSystem)
					{
						BattleScreenObject screenObject = battleViewSystem.GetScreenObject();
						Vector3 offset = Vector3.forward * 0.5f; // computed and discarded in the binary (01762d44)
						if (screenObject != null && (macro.drawType == SEQ_DEF_EFF_DRAWTYPE.SEQ_DEF_EFF_DRAWTYPE_SCREEN || macro.drawType == SEQ_DEF_EFF_DRAWTYPE.SEQ_DEF_EFF_DRAWTYPE_BEFORE))
							iPtrParticle.SetRenderCamera(screenObject);
					}
					else if (pViewSystem is ContestViewSystem contestViewSystem)
					{
						BattleScreenObject screenObject = contestViewSystem.GetScreenObject();
						Vector3 offset = Vector3.forward * 0.5f; // computed and discarded in the binary (01762d44)
						if (screenObject != null && (macro.drawType == SEQ_DEF_EFF_DRAWTYPE.SEQ_DEF_EFF_DRAWTYPE_SCREEN || macro.drawType == SEQ_DEF_EFF_DRAWTYPE.SEQ_DEF_EFF_DRAWTYPE_BEFORE))
							iPtrParticle.SetRenderCamera(screenObject);
					}

					if (iPtrParticle.Effect == null)
						return;

					if (!iPtrVec.HasVector(param.GroupNo))
					{
						HashSet<BtlvEffectInstance> particles = new HashSet<BtlvEffectInstance>();
						particles.Add(iPtrParticle);
						iPtrVec.CreateVector(param.GroupNo, particles);
					}

					Vector3 initScale = iPtrParticle.Effect.particleSystem.transform.localScale;
					iPtrParticle.Play(x => iPtrParticle.SetScaleVec(initScale));
					if (frame > 0)
					{
						TaskParticleDelete task = new TaskParticleDelete(iPtrParticle, macro.deleteType, () => iPtrVec.DeleteVector(param.GroupNo), frame, 0);
						task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
						pViewSystem.GetTaskManager().RegisterTask(task, false);
					}
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_ParticleStop(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ParticleStop)
			{
				if (_uPtrParticleVectorHash.TryGetVector(param.GroupNo, out HashSet<BtlvEffectInstance> particles) && particles != null)
				{
					foreach (BtlvEffectInstance iPtrParticle in particles)
						iPtrParticle?.Fade();
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_ParticleDelete(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ParticleDelete macro)
			{
				if (_uPtrParticleVectorHash.TryGetVector(param.GroupNo, out HashSet<BtlvEffectInstance> particles) && particles != null)
				{
					foreach (BtlvEffectInstance iPtrParticle in particles)
						iPtrParticle?.Kill(macro.deleteType == SEQ_DEF_PARTICLE_DELETE.SEQ_DEF_PARTICLE_DELETE_KILL);

					particles.Clear();
					_uPtrParticleVectorHash.DeleteVector(param.GroupNo);
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_ParticleMovePosition(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ParticleMovePosition macro)
			{
				int frame = CALC_FRAME(param);
				if (_uPtrParticleVectorHash.TryGetVector(param.GroupNo, out HashSet<BtlvEffectInstance> particles) && particles != null && particles.Count != 0)
				{
					foreach (BtlvEffectInstance iPtrObj in particles)
					{
						if (iPtrObj.IsScreenEffect && !macro.relative)
							continue;

						Vector3 pos = new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f);
						if (macro.isRotPos)
							Mathe.Btlv.RotDegXZ(ref pos, -iPtrObj.GetRotationVec().y);

						if (macro.relative)
							pos = pos + iPtrObj.GetTranslationVec();

						Vector3 retPos = iPtrObj.GetTranslationVec();
						SetVectorSelectElem(ref retPos, ref pos, macro.enableElem);
						if (frame == 0)
						{
							iPtrObj.SetTranslationVec(retPos);
						}
						else
						{
							TaskVectorControl task = new TaskVectorControl(iPtrObj.GetTranslationVec(), retPos, ((EaseFunc)macro.move).GetEase(), frame, x => iPtrObj.SetTranslationVec(x));
							task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
							pViewSystem.GetTaskManager().RegisterTask(task, true);
						}
					}
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_ParticleMoveRelativePoke(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ParticleMoveRelativePoke macro)
			{
				int frame = CALC_FRAME(param);
				if (_uPtrParticleVectorHash.TryGetVector(param.GroupNo, out HashSet<BtlvEffectInstance> particles) && particles != null)
				{
					RELARIVE_POKE_OPTION opt = RELARIVE_POKE_OPTION.Factory();
					opt.m_node = macro.node;
					opt.m_offset = new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f);
					opt.m_rate = macro.rate;
					opt.m_adjustFlip = macro.isFlip;
					opt.m_adjustScale = macro.isScale;
					opt.m_autoRotateModel = macro.isRot;
					opt.m_autoRotatePos = macro.isRotPos;
					opt.m_forceUpdate = macro.forceUpdate;
					opt.m_moveType = (int)macro.move;
					opt.m_targetElem = macro.enableElem;
					int index = 0;
					foreach (BtlvEffectInstance iPtrObj in particles)
					{
						opt.m_vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, index);
						opt.m_vposSub = pViewSystem.SeqComFunc_GetTargetPokeSub(macro.trg);
						pViewSystem.SeqComFunc_MoveRelativePoke(iPtrObj, frame, opt, false);
						index++;
					}
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_ParticleMoveRelativeTrainer(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ParticleMoveRelativeTrainer macro)
			{
				int frame = CALC_FRAME(param);
				if (_uPtrParticleVectorHash.TryGetVector(param.GroupNo, out HashSet<BtlvEffectInstance> particles))
				{
					foreach (BtlvEffectInstance iPtrObj in particles)
					{
						BOTrainer trainer = pViewSystem.SeqComFunc_GetTargetChara(macro.trg, 0) as BOTrainer;
						if (trainer == null)
							return;

						Transform joint = trainer.Entity.GetJointByName(macro.node);
						if (joint == null)
							return;

						Vector3 jointPos = joint.position;
						if (frame != 0)
						{
							TaskVectorControl task = new TaskVectorControl(iPtrObj.GetTranslationVec(), jointPos + new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f), ((EaseFunc)macro.move).GetEase(), frame, x => iPtrObj.SetTranslationVec(x));
							task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
							pViewSystem.GetTaskManager().RegisterTask(task, true);
						}
						else
						{
							iPtrObj.SetTranslationVec(jointPos + new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f));
						}
					}
				}
			}
		}
