		private void BTL_SEQ_FUNC_DEF_ParticleMoveRelativeParticle(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ParticleMoveRelativeParticle macro)
			{
				int frame = CALC_FRAME(param);
				if (_uPtrParticleVectorHash.TryGetVector(param.GroupNo, out HashSet<BtlvEffectInstance> particles) && _uPtrParticleVectorHash.TryGetVector(macro.trg, out HashSet<BtlvEffectInstance> targets))
				{
					foreach (BtlvEffectInstance iPtrObj in particles)
					{
						foreach (BtlvEffectInstance target in targets)
						{
							Vector3 targetPos = target.GetTranslationVec();
							Vector3 ofs = new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f);
							if (macro.isRotPos)
								Mathe.Btlv.RotDegXZ(ref ofs, -target.GetRotationVec().y);

							Vector3 pos = targetPos + ofs;
							if (frame != 0)
							{
								TaskVectorControl task = new TaskVectorControl(iPtrObj.GetTranslationVec(), pos, ((EaseFunc)macro.move).GetEase(), frame, x => iPtrObj.SetTranslationVec(x));
								task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
								pViewSystem.GetTaskManager().RegisterTask(task, true);
							}
							else
							{
								iPtrObj.SetTranslationVec(pos);
							}
						}
					}
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_ParticleScale(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ParticleScale macro)
			{
				int frame = CALC_FRAME(param);
				if (_uPtrParticleVectorHash.TryGetVector(param.GroupNo, out HashSet<BtlvEffectInstance> particles))
				{
					foreach (BtlvEffectInstance iPtrObj in particles)
					{
						if (iPtrObj.Effect == null)
							continue;

						Vector3 scale = macro.scale;
						if (macro.relative)
						{
							Vector3 now = iPtrObj.GetScaleVec();
							scale = new Vector3(scale.x * now.x, scale.y * now.y, scale.z * now.z);
						}

						if (frame == 0)
						{
							iPtrObj.SetScaleVec(scale);
						}
						else
						{
							TaskVectorControl task = new TaskVectorControl(iPtrObj.GetScaleVec(), scale, ((EaseFunc)macro.move).GetEase(), frame, x => iPtrObj.SetScaleVec(x));
							task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
							pViewSystem.GetTaskManager().RegisterTask(task, true);
						}
					}
				}
			}
		}
