				{
					int index = 0;
					foreach (BtlvEffectInstance iPtrObj in particles)
					{
						BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.dirPoke, index);
						Vector3 rot = iPtrObj.GetRotationVec();
						pViewSystem.SeqComFunc_CalcPokeDir(iPtrObj.GetTranslationVec(), vpos, macro.node, ref rot, macro.vertical);
						rot.y -= macro.ofs;
						if (frame == 0)
						{
							iPtrObj.SetRotationVec(rot);
						}
						else
						{
							TaskVectorControl task = new TaskVectorControl(iPtrObj.GetRotationVec(), rot, ((EaseFunc)macro.move).GetEase(), frame, x => iPtrObj.SetRotationVec(x));
							task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
							pViewSystem.GetTaskManager().RegisterTask(task, true);
						}

						index++;
					}
				}
			}
