		private void BTL_SEQ_FUNC_DEF_ParticleLengthScale(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ParticleLengthScale macro)
			{
				int frame = CALC_FRAME(param);
				if (_uPtrParticleVectorHash.TryGetVector(param.GroupNo, out HashSet<BtlvEffectInstance> particles))
				{
					int index = 0;
					foreach (BtlvEffectInstance iPtrObj in particles)
					{
						BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, index);
						if (vpos == BtlvPos.BTL_VPOS_ERROR)
							continue;

						BOPokemon poke = pViewSystem.GetPokeModel(vpos);
						Vector3 nodePos = Vector3.zero;
						poke.GetNodePositionSequence(macro.node, ref nodePos);
						float len = Vector3.Distance(iPtrObj.GetCalcTranslation(), nodePos) / (macro.baseLen * 0.01f);
						Vector3 scale = new Vector3(len, len, len);
						Vector3 retScale = iPtrObj.GetScaleVec();
						SetVectorSelectElem(ref retScale, ref scale, macro.scale);
						if (frame != 0)
						{
							TaskVectorControl task = new TaskVectorControl(iPtrObj.GetScaleVec(), retScale, ((EaseFunc)macro.move).GetEase(), frame, x => iPtrObj.SetScaleVec(x));
							task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
							pViewSystem.GetTaskManager().RegisterTask(task, true);
						}
						else
						{
							iPtrObj.SetScaleVec(retScale);
						}

						index++;
					}
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_ParticleFollowModel(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ParticleFollowModel macro)
			{
				if (_uPtrParticleVectorHash.TryGetVector(param.GroupNo, out HashSet<BtlvEffectInstance> particles))
				{
					if (macro.grpNo != -1)
					{
						foreach (BtlvEffectInstance iPtrObj in particles)
						{
							// Shipped quirk (01767064): the model group is looked up with param.GroupNo, not macro.grpNo.
							if (_uPtrModelHash.TryGetVector(param.GroupNo, out HashSet<ObjectEntity> models))
							{
								foreach (ObjectEntity model in models)
								{
									iPtrObj.AttachModel(model, model.GetLocatorByName(macro.node), macro.isPos, macro.isRot, macro.isScl, macro.isAnimScl, false);
									iPtrObj.SetTranslationOffset(macro.pos);
									iPtrObj.SetRotationVecOffset(macro.rot);
								}
							}
						}
					}
					else
					{
						foreach (BtlvEffectInstance iPtrObj in particles)
							iPtrObj.DetachModel();
					}
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_ParticleFollowPoke(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ParticleFollowPoke macro)
			{
				if (_uPtrParticleVectorHash.TryGetVector(param.GroupNo, out HashSet<BtlvEffectInstance> particles))
				{
					if (macro.isEnable)
					{
						int index = 0;
						foreach (BtlvEffectInstance iPtrObj in particles)
						{
							BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.pos, index);
							if (vpos == BtlvPos.BTL_VPOS_ERROR)
								continue;

							iPtrObj.AttachPoke(pViewSystem.GetPokeModel(vpos), macro.node, macro.isRot, macro.isScl, false);
							iPtrObj.SetTranslationOffset(new Vector3(macro.posOfs.x * -0.01f, macro.posOfs.y * 0.01f, macro.posOfs.z * 0.01f));
							index++;
						}
					}
					else
					{
						foreach (BtlvEffectInstance iPtrObj in particles)
							iPtrObj.DetachPoke();
					}
				}
			}
		}
