		private void BTL_SEQ_FUNC_DEF_PokemonMovePosition(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is PokemonMovePosition macro)
			{
				Vector3 pos = new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f);
				int frame = CALC_FRAME(param);
				BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, 0);
				BtlvPos vposSub = pViewSystem.SeqComFunc_GetTargetPokeSub(macro.trg);
				if (macro.isFlip)
				{
					if (pViewSystem.SeqComFunc_IsFlipEffect(vpos, vposSub))
						pos.x = -pos.x;
				}

				int num = 1;
				if (macro.trg == SEQ_DEF_POS.SEQ_DEF_POS_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					BOPokemon pokeModel;
					Vector3 movePos = pos;
					BtlvPos target = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, i);
					if (target == BtlvPos.BTL_VPOS_ERROR)
						continue;

					pokeModel = pViewSystem.GetPokeModel(target);
					if (pokeModel == null)
						return; // shipped: leaves the whole command, not only this target (01768564)

					if (macro.isRotPos)
						Mathe.Btlv.RotDegXZ(ref movePos, -pokeModel.GetRotationVec().y);

					if (macro.relative)
						movePos = pokeModel.GetTranslationVec() + movePos;

					Vector3 nowPos = pokeModel.GetTranslationVec();
					SetVectorSelectElem(ref nowPos, ref movePos, macro.enableElem);
					if (frame == 0)
					{
						pokeModel.SetTranslationVec(nowPos);
						continue;
					}

					TaskVectorControl task = new TaskVectorControl(pokeModel.GetTranslationVec(), nowPos, ((EaseFunc)macro.move).GetEase(), frame, x => pokeModel.SetTranslationVec(x));
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(task, true);
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_PokemonMoveRelativePoke(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is PokemonMoveRelativePoke macro)
			{
				int frame = CALC_FRAME(param);
				RELARIVE_POKE_OPTION opt = RELARIVE_POKE_OPTION.Factory();
				opt.m_node = macro.node;
				opt.m_offset = new Vector3(macro.ofs.x * -0.01f, macro.ofs.y * 0.01f, macro.ofs.z * 0.01f);
				opt.m_rate = macro.rate;
				opt.m_adjustFlip = macro.isFlip;
				opt.m_adjustScale = false;
				opt.m_autoRotateModel = macro.isRot;
				opt.m_autoRotatePos = macro.isRotPos;
				opt.m_moveType = (int)macro.move;
				opt.m_targetElem = macro.enableElem;

				int num = 1;
				if (macro.posTrg == SEQ_DEF_POS.SEQ_DEF_POS_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					opt.m_vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.posTrg, i);
					opt.m_vposSub = pViewSystem.SeqComFunc_GetTargetPokeSub(macro.posTrg);
					BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.moveTrg, i);
					if (vpos == BtlvPos.BTL_VPOS_ERROR)
						continue;

					pViewSystem.SeqComFunc_MoveRelativePoke(pViewSystem.GetPokeModel(vpos), frame, opt, false);
				}
			}
		}
