		private void BTL_SEQ_FUNC_DEF_PokemonScale(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is PokemonScale macro)
			{
				int frame = CALC_FRAME(param);
				int num = 1;
				if (macro.trg == SEQ_DEF_POS.SEQ_DEF_POS_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					BOPokemon pokeModel;
					BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, i);
					if (vpos == BtlvPos.BTL_VPOS_ERROR)
						continue;

					pokeModel = pViewSystem.GetPokeModel(vpos);
					if (pokeModel == null)
						continue;

					Vector3 scale = macro.scale;
					if (macro.relative)
					{
						Vector3 nowScale = pokeModel.GetScaleVec();
						scale = new Vector3(scale.x * nowScale.x, scale.y * nowScale.y, scale.z * nowScale.z);
					}

					if (frame == 0)
					{
						pokeModel.SetScaleVec(scale);
						continue;
					}

					TaskVectorControl task = new TaskVectorControl(pokeModel.GetScaleVec(), scale, ((EaseFunc)macro.move).GetEase(), frame, x =>
					{
						if (pokeModel != null)
							pokeModel.SetScaleVec(x);
					});
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(task, true);
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_PokemonScaleNode(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is PokemonScaleNode macro)
			{
				int frame = CALC_FRAME(param);
				int num = 1;
				if (macro.trg == SEQ_DEF_POS.SEQ_DEF_POS_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					BOPokemon pokeModel;
					BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, i);
					if (vpos == BtlvPos.BTL_VPOS_ERROR)
						continue;

					pokeModel = pViewSystem.GetPokeModel(vpos);
					if (pokeModel == null)
						continue;

					Vector3 scale = macro.scale;
					if (macro.relative)
					{
						Vector3 nowScale = pokeModel.GetScaleVec();
						scale = new Vector3(scale.x * nowScale.x, scale.y * nowScale.y, scale.z * nowScale.z);
					}

					Vector3 nowNodeScaleTranslation = pokeModel.GetNodeScaleTranslation();
					Vector3 nodeScaleTranslation = Vector3.zero;
					Vector3 basePos = Vector3.zero;
					Vector3 nodePos = Vector3.zero;
					pokeModel.GetNodeBasePositionSequence(SEQ_DEF_NODE.SEQ_DEF_NODE_ORI_ORIGIN, ref basePos);
					pokeModel.GetNodeBasePositionSequence(macro.node, ref nodePos);
					Vector3 diff = nodePos - basePos;
					Vector3 nowScaleVec = pokeModel.GetScaleVec();
					Vector3 rate = new Vector3(scale.x / nowScaleVec.x, scale.y / nowScaleVec.y, scale.z / nowScaleVec.z);
					nodeScaleTranslation.Set(diff.x - diff.x * rate.x, diff.y - diff.y * rate.y, diff.z - diff.z * rate.z);
					nodeScaleTranslation = nodeScaleTranslation + nowNodeScaleTranslation;

					Vector3 translation = pokeModel.GetTranslationVec();
					if (macro.origin)
					{
						translation = translation + (nodeScaleTranslation - nowNodeScaleTranslation);
						nodeScaleTranslation = nowNodeScaleTranslation;
					}

					if (macro.reset)
						nodeScaleTranslation = Vector3.zero;

					if (frame == 0)
					{
						pokeModel.SetScaleVec(scale);
						pokeModel.SetTranslationVec(translation);
						pokeModel.SetNodeScaleTranslation(nodeScaleTranslation);
						continue;
					}

					TaskVectorControl scaleTask = new TaskVectorControl(pokeModel.GetScaleVec(), scale, ((EaseFunc)macro.move).GetEase(), frame, x => pokeModel.SetScaleVec(x));
					scaleTask.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(scaleTask, true);

					if (macro.origin)
					{
						TaskVectorControl translationTask = new TaskVectorControl(pokeModel.GetTranslationVec(), translation, ((EaseFunc)macro.move).GetEase(), frame, x => pokeModel.SetTranslationVec(x));
						translationTask.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
						pViewSystem.GetTaskManager().RegisterTask(translationTask, true);
					}

					TaskVectorControl nodeTask = new TaskVectorControl(pokeModel.GetNodeScaleTranslation(), nodeScaleTranslation, ((EaseFunc)macro.move).GetEase(), frame, x => pokeModel.SetNodeScaleTranslation(x));
					nodeTask.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(nodeTask, true);
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_PokemonRotate(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is PokemonRotate macro)
			{
				int frame = CALC_FRAME(param);
				int num = 1;
				if (macro.trg == SEQ_DEF_POS.SEQ_DEF_POS_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					BOPokemon pokeModel;
					BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, i);
					if (vpos == BtlvPos.BTL_VPOS_ERROR)
						continue;

					BtlvPos vposSub = pViewSystem.SeqComFunc_GetTargetPokeSub(macro.trg);
					pokeModel = pViewSystem.GetPokeModel(vpos);

					Vector3 rot = macro.scale;
					rot.y = -rot.y;
					if (macro.relative)
					{
						// non-short-circuit: the flip test runs even when isFlip is off (0176a534-0176a554)
						if (macro.isFlip & pViewSystem.SeqComFunc_IsFlipEffect(vpos, vposSub))
						{
							rot.x = -rot.x;
							rot.y = -rot.y;
							rot.z = -rot.z;
						}

						rot = rot + pokeModel.GetRotationVec();
					}

					if (frame == 0)
					{
						pokeModel.SetRotationVec(rot);
						continue;
					}

					TaskVectorControl task = new TaskVectorControl(pokeModel.GetRotationVec(), rot, ((EaseFunc)macro.move).GetEase(), frame, x => pokeModel.SetRotationVec(x));
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(task, true);
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_PokemonRotatePoke(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is PokemonRotatePoke macro)
			{
				int frame = CALC_FRAME(param);
				int num = 1;
				if (macro.trgPoke == SEQ_DEF_POS.SEQ_DEF_POS_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				BtlvPos dirPos = pViewSystem.SeqComFunc_GetTargetPoke(macro.dirPoke, 0);
				for (int i = 0; i < num; i++)
				{
					BOPokemon pokeModel;
					BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trgPoke, i);
					if (vpos == BtlvPos.BTL_VPOS_ERROR)
						continue;

					pokeModel = pViewSystem.GetPokeModel(vpos);
					Vector3 rot = pokeModel.GetRotationVec();
					pViewSystem.SeqComFunc_CalcPokeDir(pokeModel.GetTranslationVec(), dirPos, macro.node, ref rot, false);
					rot.y -= macro.ofs;
					if (frame == 0)
					{
						pokeModel.SetRotationVec(rot);
						continue;
					}

					TaskVectorControl task = new TaskVectorControl(pokeModel.GetRotationVec(), rot, ((EaseFunc)macro.move).GetEase(), frame, x => pokeModel.SetRotationVec(x));
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(task, true);
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_PokemonRotateSpecialPos(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is PokemonRotateSpecialPos macro)
			{
				int frame = CALC_FRAME(param);
				int num = 1;
				if (macro.trgPoke == SEQ_DEF_POS.SEQ_DEF_POS_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				Vector3 retPos = Vector3.zero;
				Vector3 retRot = Vector3.zero;
				pViewSystem.SeqComFunc_GetSpecialPos(macro.pos, ref retPos, ref retRot);

				BtlvPos vpos;
				switch (macro.pos)
				{
					case SEQ_DEF_SPPOS.SEQ_DEF_SPPOS_SELF_FIELD:
						vpos = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK, 0);
						break;
					case SEQ_DEF_SPPOS.SEQ_DEF_SPPOS_ENEMY_FIELD:
					case SEQ_DEF_SPPOS.SEQ_DEF_SPPOS_ENEMY_CENTER:
						vpos = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_DEFTRG, 0);
						break;
					default:
						vpos = BtlvPos.BTL_VPOS_ERROR;
						break;
				}

				Vector3 ofs = new Vector3(macro.ofs.x * -0.01f, macro.ofs.y * 0.01f, macro.ofs.z * 0.01f);
				if (macro.isFlip)
				{
					if (pViewSystem.SeqComFunc_IsFlipEffect(vpos, vpos))
						ofs.x = -ofs.x;
				}

				if (macro.isRot)
					Mathe.Btlv.RotDegXZ(ref ofs, -retRot.y);

				retPos = retPos + ofs;

				for (int i = 0; i < num; i++)
				{
					BOPokemon pokeModel;
					BtlvPos target = pViewSystem.SeqComFunc_GetTargetPoke(macro.trgPoke, i);
					if (target == BtlvPos.BTL_VPOS_ERROR)
						continue;

					pokeModel = pViewSystem.GetPokeModel(target);
					Vector3 rot = Vector3.zero;
					Vector3 nowRot = pokeModel.GetRotationVec();
					pViewSystem.SeqComFunc_CalcPosDir(pokeModel.GetTranslationVec(), retPos, ref rot, false);
					rot.y -= macro.rotOfs;
					if (rot.y - nowRot.y > ROTATION_ADJUST.Item1)
						rot.y -= ROTATION_ADJUST.Item2;
					if (rot.y - nowRot.y < -ROTATION_ADJUST.Item1)
						rot.y += ROTATION_ADJUST.Item2;

					if (frame == 0)
					{
						pokeModel.SetRotationVec(rot);
						continue;
					}

					TaskVectorControl task = new TaskVectorControl(nowRot, rot, ((EaseFunc)macro.move).GetEase(), frame, x => pokeModel.SetRotationVec(x));
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(task, true);
				}
			}
		}
