		private void BTL_SEQ_FUNC_DEF_PokemonRotateNode(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is PokemonRotateNode macro)
			{
				int frame = CALC_FRAME(param);
				int num = 1;
				if (macro.trg == SEQ_DEF_POS.SEQ_DEF_POS_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					BOPokemon pokeModel;
					BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, i);
					if (vpos == BtlvPos.BTL_VPOS_ERROR)
						continue;

					BtlvPos vposSub = pViewSystem.SeqComFunc_GetTargetPokeSub(macro.trg);
					pokeModel = pViewSystem.GetPokeModel(vpos);

					Vector3 rot = macro.scale;
					rot.y = -rot.y;
					if (macro.relative)
					{
						if (macro.isFlip && pViewSystem.SeqComFunc_IsFlipEffect(vpos, vposSub))
						{
							rot.x = -rot.x;
							rot.y = -rot.y;
							rot.z = -rot.z;
						}

						rot = rot + pokeModel.GetRotationVec();
					}

					if (frame == 0)
					{
						Vector3 basePos = Vector3.zero;
						Vector3 nodePos = Vector3.zero;
						pokeModel.GetNodeBasePositionSequence(SEQ_DEF_NODE.SEQ_DEF_NODE_ORI_ORIGIN, ref basePos);
						pokeModel.GetNodeBasePositionSequence(macro.node, ref nodePos);
						Vector3 diff = basePos - nodePos;
						Vector3 calcScale = pokeModel.GetCalcScale();
						diff.Set(calcScale.x * diff.x, calcScale.y * diff.y, calcScale.z * diff.z);
						Vector3 unused = Vector3.zero; // dead in the binary (0176bce0), kept for the call
						Vector3 radian = Vector3.zero;
						radian.Set(rot.x * Mathf.Deg2Rad, rot.y * Mathf.Deg2Rad, rot.z * Mathf.Deg2Rad);
						// shipped: Quaternion.Euler is given radians (0176bcf0-0176bd18)
						pokeModel.SetNodeRotateTranslation(Mathe.Btlv.Rotate(diff, Quaternion.Euler(radian)) - diff);
						pokeModel.SetRotationVec(rot);
						continue;
					}

					TaskVectorControl task = new TaskVectorControl(pokeModel.GetRotationVec(), rot, ((EaseFunc)macro.move).GetEase(), frame, x =>
					{
						Vector3 basePos = Vector3.zero;
						Vector3 nodePos = Vector3.zero;
						pokeModel.GetNodeBasePositionSequence(SEQ_DEF_NODE.SEQ_DEF_NODE_ORI_ORIGIN, ref basePos);
						pokeModel.GetNodeBasePositionSequence(macro.node, ref nodePos);
						Vector3 diff = basePos - nodePos;
						Vector3 calcScale = pokeModel.GetCalcScale();
						diff.Set(calcScale.x * diff.x, calcScale.y * diff.y, calcScale.z * diff.z);
						Vector3 unused = Vector3.zero; // dead in the binary (01c7a5cc), kept for the call
						Vector3 radian = Vector3.zero;
						radian.Set(x.x * Mathf.Deg2Rad, x.y * Mathf.Deg2Rad, x.z * Mathf.Deg2Rad);
						pokeModel.SetNodeRotateTranslation(Mathe.Btlv.Rotate(diff, Quaternion.Euler(radian)) - diff);
						pokeModel.SetRotationVec(x);
					});
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(task, true);
				}
			}
		}
