		private void BTL_SEQ_FUNC_DEF_PokemonVisibleOther(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is PokemonVisibleOther macro)
			{
				bool[] isOther = new bool[(int)BtlvPos.BTL_VPOS_NUM];
				for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
				{
					BOPokemon pokeModel = pViewSystem.GetPokeModel((BtlvPos)i);
					isOther[i] = pokeModel != null && pokeModel.IsEnable;
				}

				BtlvPos atkPos = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK, 0);
				if (atkPos != BtlvPos.BTL_VPOS_ERROR)
					isOther[(int)atkPos] = false;

				int num = pViewSystem.SeqComFunc_GetTargetPokeNum(false);
				for (int i = 0; i < num; i++)
				{
					BtlvPos defPos = pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_DEF, i);
					if (defPos != BtlvPos.BTL_VPOS_ERROR)
						isOther[(int)defPos] = false;
				}

				for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
				{
					if (!isOther[i])
						continue;

					BOPokemon pokeModel = pViewSystem.GetPokeModel((BtlvPos)i);
					if (pokeModel != null)
						pokeModel.SetVisible(macro.visible);
				}
			}
		}
