		private void BTL_SEQ_FUNC_DEF_PokemonMotion(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is PokemonMotion macro)
			{
				int num = 1;
				if (macro.trg == SEQ_DEF_POS.SEQ_DEF_POS_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, i);
					if (vpos == BtlvPos.BTL_VPOS_ERROR)
						continue;

					BOPokemon pokeModel = pViewSystem.GetPokeModel(vpos);

					// rodata table @03bb522c (32 entries, default Max)
					BattlePokemonEntity.AnimationState state;
					switch (macro.motion)
					{
						case SEQ_DEF_MOTION.MOTION_WAIT:
						case SEQ_DEF_MOTION.MOTION_LAND:
							state = BattlePokemonEntity.AnimationState.WaitA01;
							break;
						case SEQ_DEF_MOTION.MOTION_ATK_WAIT_B:
							state = BattlePokemonEntity.AnimationState.WaitB01;
							break;
						case SEQ_DEF_MOTION.MOTION_ATK_WAIT_C:
							state = BattlePokemonEntity.AnimationState.WaitC01;
							break;
						case SEQ_DEF_MOTION.MOTION_ATK_BUTSURI1:
						case SEQ_DEF_MOTION.POKE_MOTION_ATK_BUTSURI:
							state = BattlePokemonEntity.AnimationState.Buturi01;
							break;
						case SEQ_DEF_MOTION.MOTION_ATK_BUTSURI2:
							state = BattlePokemonEntity.AnimationState.Buturi02;
							break;
						case SEQ_DEF_MOTION.MOTION_ATK_BUTSURI3:
							state = BattlePokemonEntity.AnimationState.Buturi03;
							break;
						case SEQ_DEF_MOTION.MOTION_ATK_TOKUSHU1:
						case SEQ_DEF_MOTION.POKE_MOTION_ATK_TOKUSHU:
							state = BattlePokemonEntity.AnimationState.Tokusyu01;
							break;
						case SEQ_DEF_MOTION.MOTION_ATK_TOKUSHU2:
							state = BattlePokemonEntity.AnimationState.Tokusyu02;
							break;
						case SEQ_DEF_MOTION.MOTION_ATK_TOKUSHU3:
							state = BattlePokemonEntity.AnimationState.Tokusyu03;
							break;
						case SEQ_DEF_MOTION.MOTION_DAMAGE:
							state = BattlePokemonEntity.AnimationState.Damage;
							break;
						case SEQ_DEF_MOTION.MOTION_DOWN:
							state = BattlePokemonEntity.AnimationState.Down;
							break;
						default:
							state = BattlePokemonEntity.AnimationState.Max;
							break;
					}

					BTLV_WAZA_EFF_PARAM wazaParam = pViewSystem.GetWazaParam();
					if (pViewSystem.SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK, 0) == vpos)
						state = pokeModel.CheckReplaceWazaAnimationState(state, wazaParam.m_id);

					pokeModel.ChangeAnimStatePoke(state);
				}
			}
		}
