		private void BTL_SEQ_FUNC_DEF_PokemonShaderCol(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is PokemonShaderCol macro)
			{
				int frame = CALC_FRAME(param);
				int num = 1;
				if (macro.trg == SEQ_DEF_POS.SEQ_DEF_POS_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					BOPokemon pokeModel;
					BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, i);
					if (vpos == BtlvPos.BTL_VPOS_ERROR)
						continue;

					pokeModel = pViewSystem.GetPokeModel(vpos);
					BTL_POKEPARAM bpp = pViewSystem.GetBattlePokeParam(vpos);
					if (pokeModel == null)
						continue;

					if (pViewSystem is BattleViewSystem viewSystem)
					{
						BTL_POKEPARAM enemyBpp = pViewSystem.GetBattlePokeParam(BtlvPos.BTL_VPOS_FAR_1);
						// shipped: the whole command stops for Origin Forme Giratina as the enemy of a no-ball battle (0176d840-0176d8c8)
						if (viewSystem.GetSetupStatusFlag(BTL_STATUS_FLAG.BTL_STATUS_FLAG_CANT_USE_BALL) && bpp != null && enemyBpp != null &&
							bpp.GetID() == enemyBpp.GetID() && bpp.GetMonsNo() == (ushort)Pml.MonsNo.GIRATHINA && bpp.GetFormNo() == 1)
							return;
					}

					Vector4 startColor = macro.start_col; // unused: only its op_Implicit call survives (0176d658)
					Vector4 endColor = macro.end_col;
					if (frame == 0)
					{
						pokeModel.Entity.FixMultiplierColor = endColor;
						continue;
					}

					TaskVectorControl task = new TaskVectorControl(macro.start_col, macro.end_col, EaseFunc.LINEAR.GetEase(), frame, x => pokeModel.Entity.FixMultiplierColor = (Color)(Vector4)x);
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(task, true);
				}
			}
		}
