		private void BTL_SEQ_FUNC_DEF_PokemonSpMoveShake(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is PokemonSpMoveShake macro)
			{
				int frame = CALC_FRAME(param);
				BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, 0);
				BtlvPos vposSub = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, 0);
				if (macro.isFlip && pViewSystem.SeqComFunc_IsFlipEffect(vpos, vposSub))
				{
					if (macro.axis == SEQ_DEF_AXIS.SEQ_DEF_AXIS_X_ROT || macro.axis == SEQ_DEF_AXIS.SEQ_DEF_AXIS_X)
					{
						// shipped: the offset is added to the macro itself, so it accumulates on every run (0176df68-0176df78)
						macro.sdec += 0.5f;
						macro.edec += 0.5f;
					}
				}

				int num = 1;
				if (macro.trg == SEQ_DEF_POS.SEQ_DEF_POS_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					BOPokemon pokeModel;
					BtlvPos target = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, i);
					if (target == BtlvPos.BTL_VPOS_ERROR)
						continue;

					pokeModel = pViewSystem.GetPokeModel(target);
					TaskShakeObject task = new TaskShakeObject(x => pokeModel.SetTranslationOffset(x), () => pokeModel.GetTranslationOffset(), () => pokeModel.GetRotationVec(), macro.srate, macro.erate, macro.sdec, macro.edec, frame, macro.axis);
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(task, true);
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_PokemonSetOriginScale(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			// shipped: tests the PokemonSetEnableFloat macro type (same TypeInfo 54188 as SetEnableFloat, usage lists 8936 / 8934)
			if (param.Macro is PokemonSetEnableFloat macro)
			{
				int num = 1;
				if (macro.trg == SEQ_DEF_POS.SEQ_DEF_POS_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, i);
