		private void BTL_SEQ_FUNC_DEF_PostEffectDepthOfFieldSet(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is PostEffectDepthOfFieldSet macro)
			{
				int frame = CALC_FRAME(param);
				SequenceCameraObject camera = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
				if (camera == null)
					return;

				float farDepth;
				float focalLength;
				float distance;
				float blurry;
				if (macro.isReset)
				{
					BattleDataTable dataTable = BattleDataTableManager.Instance.BattleDataTable;
					farDepth = dataTable.GetBattleConstantFloat(BattleConstantKey.DEFAULT_POST_DOF_FAR_DEPTH);
					focalLength = dataTable.GetBattleConstantFloat(BattleConstantKey.DEFAULT_POST_DOF_FOCAL_LENGTH);
					distance = dataTable.GetBattleConstantFloat(BattleConstantKey.DEFAULT_POST_DOF_DISTANCE);
					blurry = (pViewSystem as BattleViewSystem).blurry;
				}
				else
				{
					farDepth = macro.farDepth;
					focalLength = macro.focalLength;
					distance = macro.distance;
					blurry = macro.blurry;
				}

				if (frame == 0)
				{
					PfxParam pfxParam = camera.GetPostEffects().GetPfxParam();
					EnvironmentController.global._Blurry = blurry;
					pfxParam.isDofEnabled = true;
					pfxParam.dofFocalLength = focalLength;
					pfxParam.dofFarDepth = farDepth;
					pfxParam.dofDistance = distance;
					camera.GetPostEffects().SetPfxParam(pfxParam, true);
					return;
				}

				TaskDepthOfFieldControl task = new TaskDepthOfFieldControl(camera, farDepth, focalLength, distance, blurry, frame, ((EaseFunc)macro.move).GetEase());
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManagerLate().RegisterTask(task, true);
			}
		}
