		private void BTL_SEQ_FUNC_DEF_PostEffectRadialBlurFlg(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is PostEffectRadialBlurFlg macro)
			{
				SequenceCameraObject camera;
				PfxParam pfxParam;
				int frame = CALC_FRAME(param);
				camera = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
				if (camera == null)
					return;

				pfxParam = camera.GetPostEffects().GetPfxParam();
				if (frame == 0 && !macro.isEnable)
				{
					if (pfxParam.isRadialBlurEnabled)
					{
						pfxParam.isRadialBlurEnabled = false;
						camera.GetPostEffects().SetPfxParam(pfxParam, true);
					}
					return;
				}

				pfxParam.isRadialBlurEnabled = true;
				camera.GetPostEffects().SetPfxParam(pfxParam, true);
				if (frame > 0 && macro.isEnable)
				{
					TaskFinishFuncCall task = new TaskFinishFuncCall(frame, () =>
					{
						pfxParam.isRadialBlurEnabled = false;
						camera.GetPostEffects().SetPfxParam(pfxParam, true);
					});
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManagerLate().RegisterTask(task, true);
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_PostEffectRadialBlurSet(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is PostEffectRadialBlurSet macro)
			{
				int frame = CALC_FRAME(param);
				SequenceCameraObject camera = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
				if (camera == null)
					return;

				if (frame == 0)
				{
					PfxParam pfxParam = camera.GetPostEffects().GetPfxParam();
					pfxParam.isRadialBlurEnabled = true;
					pfxParam.radialBlurCenter = macro.center;
					pfxParam.radialBlurIntensity = macro.intensity;
					pfxParam.radialBlurNumSamples = macro.numSamples;
					camera.GetPostEffects().SetPfxParam(pfxParam, true);
					return;
				}

				TaskRadialBlurControl task = new TaskRadialBlurControl(camera, macro.center, macro.intensity, macro.numSamples, frame, ((EaseFunc)macro.move).GetEase());
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManagerLate().RegisterTask(task, true);
			}
		}
