		private void BTL_SEQ_FUNC_DEF_TrainerMove(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is TrainerMove macro)
			{
				int frame = CALC_FRAME(param);
				int num = 1;
				if (macro.trg == SEQ_DEF_TRAINER_ADD.SEQ_DEF_TRAINER_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					BattleViewCharacter trainer;
					trainer = pViewSystem.SeqComFunc_GetTargetChara(macro.trg, i);
					if (trainer != null)
					{
						Vector3 pos = new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f);
						if (macro.relative)
							pos = pos + trainer.GetTranslationVec();

						if (frame == 0)
						{
							trainer.SetTranslationVec(pos);
							continue;
						}

						TaskVectorControl task = new TaskVectorControl(trainer.GetTranslationVec(), pos, ((EaseFunc)macro.move).GetEase(), frame, x => trainer.SetTranslationVec(x));
						task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
						pViewSystem.GetTaskManager().RegisterTask(task, true);
					}
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_TrainerMoveRelativePoke(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is TrainerMoveRelativePoke macro)
			{
				int frame = CALC_FRAME(param);
				RELARIVE_POKE_OPTION opt = RELARIVE_POKE_OPTION.Factory();
				opt.m_node = macro.node;
				opt.m_offset = new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f);
				opt.m_rate = macro.rate;
				opt.m_adjustFlip = macro.isFlip;
				opt.m_adjustScale = macro.isScale;
				opt.m_autoRotateModel = macro.isRot;
				opt.m_autoRotatePos = macro.isRotPos;
				opt.m_moveType = (int)macro.move;
				opt.m_targetElem = macro.enableElem;

				int num = 1;
				if (macro.moveTrg == SEQ_DEF_TRAINER_ADD.SEQ_DEF_TRAINER_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					BattleViewCharacter trainer = pViewSystem.SeqComFunc_GetTargetChara(macro.moveTrg, i);
					if (trainer != null)
					{
						opt.m_vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.posTrg, 0);
						opt.m_vposSub = pViewSystem.SeqComFunc_GetTargetPokeSub(macro.posTrg);
						pViewSystem.SeqComFunc_MoveRelativePoke(trainer, frame, opt, true);
					}
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_TrainerMoveRelativeTrainer(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is TrainerMoveRelativeTrainer macro)
			{
				int frame = CALC_FRAME(param);
				int num = 1;
				if (macro.moveTrg == SEQ_DEF_TRAINER.SEQ_DEF_TRAINER_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				BOTrainer posTrainer = pViewSystem.SeqComFunc_GetTargetChara(macro.posTrg, 0) as BOTrainer;
				if (!(posTrainer != null))
					return;

				Transform posJoint = posTrainer.Entity.GetJointByName(macro.posNode);
				if (posJoint == null)
					return;

				Vector3 pos = posJoint.position + macro.pos;
				for (int i = 0; i < num; i++)
				{
					BOTrainer trainer;
					trainer = pViewSystem.SeqComFunc_GetTargetChara(macro.moveTrg, i) as BOTrainer;
					if (trainer != null)
					{
						// shipped: re-reads the POSITION trainer's posNode (not trainer / moveNode) and subtracts it from the
						// running pos, cumulatively over the targets (01770374-01770418)
						Transform moveJoint = posTrainer.Entity.GetJointByName(macro.posNode);
						if (moveJoint == null)
							return;

						pos = pos - moveJoint.position;
					}

					// shipped: no null guard here (a null trainer faults), and the frame-0 path sets the translation while the
					// task animates m_rotVecOffset (01770268 / 01770430, lambda 01c7a880)
					if (frame == 0)
					{
						trainer.SetTranslationVec(pos);
						continue;
					}

					TaskVectorControl task = new TaskVectorControl(trainer.GetRotationVecOffset(), pos, ((EaseFunc)macro.move).GetEase(), frame, x => trainer.SetRotationVecOffset(x));
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(task, true);
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_TrainerMoveReset(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is TrainerMoveReset macro)
			{
				int num = 1;
				if (macro.trg == SEQ_DEF_TRAINER_ADD.SEQ_DEF_TRAINER_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetCharaVPos((SEQ_DEF_TRAINER)macro.trg, i);
					if (vpos == BtlvPos.BTL_VPOS_ERROR)
						continue;

					pViewSystem.ResetTrainer(vpos, macro.origin);
				}
			}
		}
		private void BTL_SEQ_FUNC_DEF_TrainerMoveResetAll(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is TrainerMoveResetAll macro)
			{
				for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
