		private void BTL_SEQ_FUNC_DEF_TrainerRotate(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is TrainerRotate macro)
			{
				int frame = CALC_FRAME(param);
				int num = 1;
				if (macro.trg == SEQ_DEF_TRAINER_ADD.SEQ_DEF_TRAINER_DEF)
					num = pViewSystem.SeqComFunc_GetTargetPokeNum(true);

				for (int i = 0; i < num; i++)
				{
					BattleViewCharacter trainer;
					trainer = pViewSystem.SeqComFunc_GetTargetChara(macro.trg, i);
					Vector3 rot = macro.rot;
					if (trainer != null)
					{
						rot.y = -rot.y;
						if (macro.relative)
							rot = rot + trainer.GetRotationVec();

						if (frame == 0)
						{
							trainer.SetRotationVec(rot);
							continue;
						}

						TaskVectorControl task = new TaskVectorControl(trainer.GetRotationVec(), rot, ((EaseFunc)macro.move).GetEase(), frame, x => trainer.SetRotationVec(x));
						task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
						pViewSystem.GetTaskManager().RegisterTask(task, true);
					}
				}
			}
		}
