		public BattleSequenceSystem(global::Dpr.SequenceEditor.ISequenceViewSystem system) {
			_ISequenceViewSystem = system;
			_isPlayWaitCamera = false;
			_uPtrModelHash = new VectorHash<int, ObjectEntity>(64);
			_uPtrParticleVectorHash = new VectorHash<int, BtlvEffectInstance>(0);
			_uPtrSoundHash = new VectorHash<int, BtlvSound>(0);
		}
		public override void UnInitialize() {
			base.UnInitialize();
			_ISequenceViewSystem = null;
			_uPtrModelHash.Dispose();
			_uPtrModelHash = null;
			_uPtrParticleVectorHash.Dispose();
			_uPtrParticleVectorHash = null;
			_uPtrSoundHash.Dispose();
			_uPtrSoundHash = null;
			Mem.DelICollection(ref _removeCommands);
			Mem.DelICollection(ref _effectLoadParams);
		}
		public override void LoadSequence(string path, bool isWaitCamera = false) {
			if (string.IsNullOrWhiteSpace(path))
				return;

			IsFinishSequence = false;
			_isPlayWaitCamera = isWaitCamera;
			SequenceFile = null;
			Commands = null;
#if PC_UNLOCKED_FPS
			CurrentFrame = -1; _pcFrameFrac = 0f;
#else
			CurrentFrame = -1;
#endif
			_sequenceElapsedTime = 0.0f;
			_seqFileLoadCoroutine = Sequencer.Start(BattleViewAssetManager.LoadSequenceFile(path, file =>
			{
				IsInterpolationTime = BattleDataTableManager.Instance.BattleDataTable.GetInterpolationSequence(file.name) != null;
				SequenceFile = file;
				Commands = SequenceFile.GetCommandParams();
				int maxFrame = Commands.Max(x => x.EndFrame);
				_seqFileLoadCoroutine = null;
				MaxFrame = maxFrame + 1;
			}));
		}
		public void LoadSequence(string path, global::System.Action onLoaded, bool isWaitCamera = false) {
			if (string.IsNullOrWhiteSpace(path))
				return;

			IsFinishSequence = false;
			_isPlayWaitCamera = isWaitCamera;
			SequenceFile = null;
			Commands = null;
#if PC_UNLOCKED_FPS
			CurrentFrame = -1; _pcFrameFrac = 0f;
#else
			CurrentFrame = -1;
#endif
			_sequenceElapsedTime = 0.0f;
			_seqFileLoadCoroutine = Sequencer.Start(BattleViewAssetManager.LoadSequenceFile(path, file =>
			{
				IsInterpolationTime = BattleDataTableManager.Instance.BattleDataTable.GetInterpolationSequence(file.name) != null;
				SequenceFile = file;
				Commands = SequenceFile.GetCommandParams();
				MaxFrame = Commands.Max(x => x.EndFrame) + 1;
				_seqFileLoadCoroutine = null;
				_preLoadCoroutines?.Clear();
				onLoaded?.Invoke();
			}));
		}
		public void LoadSequenceForWaitCamera(string path) {
			LoadSequence(path, true);
		}
		public void SetupSequence() {
			// Empty
		}
		public void StartPreLoad() {
			if (SequenceFile == null)
				return;

			foreach (var command in Commands)
				CommandCallback(SequenceFile, command, true);

			if (_removeCommands != null && _removeCommands.Count != 0)
			{
				foreach (var command in _removeCommands)
					Commands.Remove(command);
				_removeCommands.Clear();
			}
		}
		public void SetupPreLoad() {
			// Empty
		}
		public override void SetPause(bool value) {
			IsPause = value;
		}
		public override void Stop() {
			OnComplete();
		}
		protected override void OnUpdate(float deltaTime, int step = 1) {
			OnUpdateCore(deltaTime, step, true);
		}
		protected override void OnLateUpdate(float deltaTime, int step) {
			OnUpdateCore(deltaTime, step, false);
		}
		private void OnUpdateCore(float deltaTime, int step, bool isUpdate) {
			for (int i = 0; i < Commands.Count; i++)
			{
				CommandParam param = Commands[i];
				if (param.Group.GrpDebug == 1)
					continue;

				// `b.lt` skip @01772368: a NaN time also skips, so the source tested `>=`
				if (_sequenceElapsedTime >= param.StartTime + _sequenceInterpolationTime && !param.IsAlreadyCalled)
				{
					if (isUpdate)
						CommandCallback(SequenceFile, param, false);
					else
						CommandCallbackLate(SequenceFile, param, false);
				}
			}
		}
		protected override void OnComplete() {
			SequenceCameraObject camera = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
			if (_ISequenceViewSystem is BattleViewSystem viewSystem)
				viewSystem.GetScreenObject().AllReleaseForce();

			camera.SetCameraAnimationmFreezeOnGround(false);
			camera.SetRotationFreeze(false);
			_isPlayWaitCamera = false;
			IsFinishSequence = true;
			base.OnComplete();
		}
		private bool CheckCanPlayCommand(global::Dpr.SequenceEditor.SequenceFile file, global::Dpr.SequenceEditor.CommandParam param, bool isSkip) {
			if (IsCommandSkip)
				return false;

			if (_ISequenceViewSystem is BattleViewSystem battleView)
			{
				if (_isPlayWaitCamera)
					return battleView.CheckCanPlayCommandWaitCamera(param);
				return battleView.CheckCanPlayCommand(param);
			}
			else if (_ISequenceViewSystem is ContestViewSystem contestView)
			{
				if (!contestView.CheckCanPlayCommand(param))
				{
					param.IsAlreadyCalled = true;
					return false;
				}
			}
			else if (_ISequenceViewSystem is Dpr.SealPreview.SealPreviewViewSystem sealView)
			{
				return sealView.CheckCanPlayCommand(param);
			}

			return true;
		}
		public override void CommandCallback(global::Dpr.SequenceEditor.SequenceFile file, global::Dpr.SequenceEditor.CommandParam param, bool isSkip) {
			ISequenceViewSystem viewSystem = _ISequenceViewSystem; // read before CheckCanPlayCommand (0177273c)
			if (!CheckCanPlayCommand(file, param, false))
				return;

			Action<SequenceFile, ISequenceViewSystem, CommandParam> action = (f, v, p) => { }; // <>c.b__482_0 (empty), never invoked
			if (isSkip)
			{
				// the delegates built in three cases are never used (shipped; ModelCreateBall builds BTL_SEQ_PRE_FUNC_DEF_ModelCreateBall)
				switch (param.CommandNo)
				{
					case CommandNo.SpecialFieldEffectCreate:
						PreloadGroundParticle(file, viewSystem, param);
						break;
					case CommandNo.ModelCreate:
						PreloadModel(file, viewSystem, param);
						break;
					case CommandNo.ParticleCreate:
						PreloadParticle(file, viewSystem, param);
						action = BTL_SEQ_PRE_FUNC_DEF_ParticleCreate;
						break;
					case CommandNo.DprParticleCreateSeal:
						PreloadParticleSeal(file, viewSystem, param);
						break;
					case CommandNo.SpecialMigawariVisible:
					case CommandNo.ContestCaptureScene:
					case CommandNo.ContestHensin:
						FindContestCommand(viewSystem, param);
						break;
					case CommandNo.DprParticleCreateCutSceneTrainer:
						PreloadParticleCutSceneTrainer(file, viewSystem, param);
						action = BTL_SEQ_FUNC_DEF_DprCutSceneTrainerParticleCreate;
						break;
					case CommandNo.CameraAnimationTrainer:
					case CommandNo.SubCameraAnimationTrainer:
					case CommandNo.DprCameraAnimationTrainer:
						PreloadCameraAnimationTrainer(file, viewSystem, param);
						break;
					case CommandNo.CameraAnimationPoke:
					case CommandNo.CameraAnimationPosition:
					case CommandNo.CameraAnimationSpecialPos:
					case CommandNo.SubCameraAnimationPoke:
					case CommandNo.SubCameraAnimationPosition:
					case CommandNo.SubCameraAnimationSpecialPos:
					case CommandNo.DprCameraAnimation:
						PreloadCameraAnimation(file, viewSystem, param);
						break;
					case CommandNo.SoundLoadBank:
						PreloadSoundBank(file, viewSystem, param);
						break;
					case CommandNo.ModelCreateBall:
						PreloadModelBall(file, viewSystem, param);
						action = BTL_SEQ_PRE_FUNC_DEF_ModelCreateBall;
						break;
					case CommandNo.PokemonAttackMotion:
					case CommandNo.ContestUserPokemonAttackMotion:
						CheckAttackMotionTimming(file, viewSystem, param);
						break;
					case CommandNo.SpecialChainAttakDefine:
						CheckSpecialChainAttakDefine(file, viewSystem, param);
						break;
				}
			}
			else
			{
				if (param.IsAlreadyCalled)
					return;

				// compare tree on the CommandNo hashes resolved per member by work/b069/swtree.py (01772784 / 017728e0)
				switch (param.CommandNo)
				{
					case CommandNo.EffCharaLightEnv:
						action = BTL_SEQ_FUNC_DEF_EffCharaLightEnv;
						break;
					case CommandNo.SpecialCheckHitCameraAABBFlg:
						action = BTL_SEQ_FUNC_DEF_SpecialCheckHitCameraAABBFlg;
						break;
					case CommandNo.EffFixParamRemoveVector:
