		private void CheckAttackMotionTimming(global::Dpr.SequenceEditor.SequenceFile file, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (pViewSystem is ContestViewSystem contestView)
			{
				if (param.Macro is ContestUserPokemonAttackMotion contestMacro)
				{
					int startFrame = param.StartFrame;
					BTLV_WAZA_EFF_PARAM wazaParam = pViewSystem.GetWazaParam();
					BOPokemon pokeModel = SceneObjectManager.Instance.GetUserWazaModelPokemon();
					MotionTimingData timingData = pokeModel.GetMotionTimingData();
					BattlePokemonEntity.AnimationState state = pokeModel.CheckReplaceWazaAnimationState(pokeModel.CheckReplaceAnimationState(contestMacro.motion.GetAnimationState()), wazaParam.m_id);
					int timing = timingData.GetTiming(state);
					wazaParam.m_enableKeyAdjust = true;
					wazaParam.m_isPlayMotion = false;
					wazaParam.m_keyDiffFrame = startFrame - wazaParam.m_startFrame - timing;
					wazaParam.m_attackMotion = state;
					contestView.SetWazaParam(wazaParam);
				}
			}
			else if (param.Macro is PokemonAttackMotion macro)
			{
				int startFrame = param.StartFrame;
				BTLV_WAZA_EFF_PARAM wazaParam = pViewSystem.GetWazaParam();
				BOPokemon pokeModel = pViewSystem.GetPokeModel(pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, 0));
				MotionTimingData timingData = pokeModel.GetMotionTimingData();
				BattlePokemonEntity.AnimationState state = pokeModel.CheckReplaceWazaAnimationState(pokeModel.CheckReplaceAnimationState(macro.motion.GetAnimationState()), wazaParam.m_id);
				int timing = timingData.GetTiming(state);
				wazaParam.m_enableKeyAdjust = true;
				wazaParam.m_isPlayMotion = false;
				wazaParam.m_keyDiffFrame = startFrame - wazaParam.m_startFrame - timing;
				wazaParam.m_attackMotion = state;
				pViewSystem.SetWazaParam(wazaParam);
			}
		}
		private void CheckSpecialChainAttakDefine(global::Dpr.SequenceEditor.SequenceFile file, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is SpecialChainAttakDefine macro)
			{
				_removeCommands.Clear();
				int[] startFrames = new int[] { macro.start1, macro.start2, macro.start3, macro.start4, macro.start5, macro.start6 };
				int[] endFrames = new int[] { macro.end1, macro.end2, macro.end3, macro.end4, macro.end5, macro.end6 };
				BTLV_WAZA_EFF_PARAM wazaParam = pViewSystem.GetWazaParam();
				int index = wazaParam.m_continueCount;
				if (startFrames[index] != 0)
					wazaParam.m_startFrame = startFrames[index];

				pViewSystem.SetWazaParam(wazaParam);
				int startFrame = startFrames[index];
				int endFrame = endFrames[index]; // unused: only its bounds check survives (01776088)
				foreach (CommandParam command in Commands)
				{
					if (command.Macro is SpecialChainAttakDefine)
						continue;

					if (command.StartFrame < startFrame)
						_removeCommands.Add(command);
				}
			}
		}
