		private void PreloadSoundBank(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is OldSoundLoadBank || param.Macro is SoundLoadBank)
			{
				SoundLoadBank macro = param.Macro as SoundLoadBank;
				if (_cachedSoundBank.TryGetValue(macro.@event, out AudioData audioData))
					return;

				AudioManager.LoadParam loadParam = default; // unused struct local (write-barriered stack store @01777ef4)
				loadParam.bankName = macro.@event;
				_cachedSoundBank.Add(macro.@event, null);
				_preLoadCoroutines.Add(Sequencer.Start(LoadSoundBank(macro.@event, x => _cachedSoundBank[macro.@event] = x)));
			}
		}
		private global::System.Collections.IEnumerator LoadSoundBank(string bankName, global::System.Action<global::Audio.AudioData> onLoaded) {
			bool isLoaded = false;
			AudioManager.LoadParam loadParam = default;
			loadParam.bankName = bankName;
			AudioManager.Instance.Load(loadParam, x =>
			{
				onLoaded?.Invoke(x);
				isLoaded = true;
			});
			while (!isLoaded)
				yield return null;
		}
		private void PreloadGroundParticle(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is SpecialFieldEffectCreate macro)
			{
				string[] fileNames = pViewSystem.GetBattleGroundEffectSystem().GetFileNames((BtlGround)macro.type);
				foreach (string fileName in fileNames)
				{
					string assetPath;
					if (fileName == string.Empty)
						continue;

					// shipped: an already cached (or missing) file ends the whole preload, not only this entry (01778300 / 01778410)
					if (BattleViewAssetManager.CachedEffectData.Any(x => x.Item1 == fileName))
						return;

					assetPath = BattleViewDefine.Path.GetFXPath(fileName);
					var eff = Array.Find(EffectManager.Instance.dbEffects.BattleEffectData, x => x.AssetBundleName == assetPath);
					if (eff == null)
						return;

					eff.AssetBundleName = eff.AssetBundleName.ToLower();
					_preLoadCoroutines.Add(Sequencer.Start(EffectManager.Instance.OpLoad(new EffectManager.LoadParam[] { eff }, (effectData, isAllLoaded) =>
					{
						BattleViewAssetManager.CachedEffectData.Add(new Tuple<string, EffectData>(fileName, effectData));
					})));
				}
			}
		}
