		public void DeleteAllVector() {
			foreach (var pair in _uPtrModelHash.RawElements)
			{
				foreach (ObjectEntity model in pair.Value)
				{
					if (model == null)
						continue;

					UnityEngine.Object.Destroy(model.gameObject);
				}
			}

			_uPtrModelHash.DeleteAllVector();

			foreach (var pair in _uPtrParticleVectorHash.RawElements)
			{
				foreach (BtlvEffectInstance effect in pair.Value)
				{
					if (effect != null)
					{
						effect.Kill(true);
						effect.Dispose();
					}
				}
			}

			_uPtrParticleVectorHash.DeleteAllVector();

			foreach (var pair in _uPtrSoundHash.RawElements)
			{
				foreach (BtlvSound sound in pair.Value)
				{
					if (sound != null)
						sound.Dispose();
				}
			}

			_uPtrSoundHash.DeleteAllVector();
		}
