		}
		public static int GetWildEncountMsg(global::Dpr.SequenceEditor.ISequenceViewSystem pViewSys, global::Dpr.Battle.Logic.BTL_POKEPARAM pDefBpp, int msgId) {
			// the first two flag tests pass a literal 0 (no BTL_STATUS_FLAG member; both calls are in the binary, 0174711c / 01747188)
			if (pViewSys.GetMainModule() != null &&
				(pViewSys.GetMainModule().GetSetupStatusFlag((BTL_STATUS_FLAG)0) ||
				 pViewSys.GetMainModule().GetSetupStatusFlag((BTL_STATUS_FLAG)0) ||
				 pViewSys.GetMainModule().GetSetupStatusFlag(BTL_STATUS_FLAG.BTL_STATUS_FLAG_LEGEND)))
			{
				msgId = BTL_STRID_STD.Encount_Wild_Legend;
			}
			else if (pViewSys.GetMainModule() != null &&
					 pViewSys.GetMainModule().IsCompetitorScenarioMode() &&
					 pViewSys.GetMainModule().GetRule() != BtlRule.BTL_RULE_RAID &&
					 pViewSys.GetMainModule().GetCaptureLevelCap() < pDefBpp.GetValue(BTL_POKEPARAM.ValueID.BPP_LEVEL))
			{
				switch (msgId)
				{
					case BTL_STRID_STD.Encount_Wild1:
						return BTL_STRID_STD.Encount_Wild_strong1;
					case BTL_STRID_STD.Encount_Wild2:
						return BTL_STRID_STD.Encount_Wild_strong2;
					case BTL_STRID_STD.Encount_Wild_Move:
						return BTL_STRID_STD.Encount_Wild_Move_strong;
					case BTL_STRID_STD.Encount_Wild_Talk:
						return BTL_STRID_STD.Encount_Wild_Talk_strong;
					case BTL_STRID_STD.Encount_Wild_Ride:
						return BTL_STRID_STD.Encount_Wild_Ride_strong;
					case BTL_STRID_STD.Encount_Wild_Legend:
						return BTL_STRID_STD.Encount_Wild_Legend_strong;
				}
			}

			return msgId;
		}
