		private void CNT_SEQ_FUNC_DEF_ContestPokemonMovePosition(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ContestPokemonMovePosition macro)
			{
				BOPokemon pokeModel;
				Vector3 pos = new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f);
				int frame = CALC_FRAME(param);
				BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, 0);
				BtlvPos vposSub = pViewSystem.SeqComFunc_GetTargetPokeSub(macro.trg);
				if (macro.isFlip && pViewSystem.SeqComFunc_IsFlipEffect(vpos, vposSub))
					pos.x = -macro.pos.x; // shipped: the raw, unscaled macro value (0177a000)

				BtlvPos target = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, 0);
				if (target == BtlvPos.BTL_VPOS_ERROR)
					return;

				pokeModel = pViewSystem.GetPokeModel(target);
				if (pokeModel == null)
					return;

				if (macro.relative)
					pos = pokeModel.GetTranslationVec() + pos;

				if (frame == 0)
				{
					pokeModel.SetTranslationVec(pos);
					return;
				}

				TaskVectorControl task = new TaskVectorControl(pokeModel.GetTranslationVec(), pos, ((EaseFunc)macro.move).GetEase(), frame, x => pokeModel.SetTranslationVec(x));
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManager().RegisterTask(task, true);
			}
		}
		private void CNT_SEQ_FUNC_DEF_PokemonMoveRelativePoke(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ContestPokemonMoveRelativePoke macro)
			{
				int frame = CALC_FRAME(param);
				RELARIVE_POKE_OPTION opt = RELARIVE_POKE_OPTION.Factory();
				opt.m_node = macro.node;
				opt.m_offset = new Vector3(macro.ofs.x * -0.01f, macro.ofs.y * 0.01f, macro.ofs.z * 0.01f);
				opt.m_rate = macro.rate;
				opt.m_adjustFlip = macro.isFlip;
				opt.m_adjustScale = false;
				opt.m_autoRotateModel = macro.isRot;
				opt.m_autoRotatePos = macro.isRotPos;
				opt.m_moveType = (int)macro.move;
				opt.m_targetElem = macro.enableElem; // shipped: macro.forceUpdate is never copied (0177a41c-0177a49c)
				opt.m_vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.posTrg, 0);
				opt.m_vposSub = pViewSystem.SeqComFunc_GetTargetPokeSub(macro.posTrg);

				BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.moveTrg, 0);
				if (vpos == BtlvPos.BTL_VPOS_ERROR)
					return;

				pViewSystem.SeqComFunc_MoveRelativePoke(pViewSystem.GetPokeModel(vpos), frame, opt, false);
			}
		}
		private void CNT_SEQ_FUNC_DEF_PokemonIntroMotion(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ContestPokemonIntroMotion macro)
			{
				float height = macro.height;
				BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, 0);
				if (vpos == BtlvPos.BTL_VPOS_ERROR)
					return;

				BOPokemon pokeModel = pViewSystem.GetPokeModel(vpos);
				LandingType landingType = pokeModel.GetPokeLandingType();
				Vector3 pos = Vector3.zero;
				if (landingType == LandingType.NORMAL)
				{
					float ofsY = height * 0.01f;
					Vector3 nodePos = Vector3.zero;
					pokeModel.GetNodePositionSequence(SEQ_DEF_NODE.SEQ_DEF_NODE_CENTER, ref nodePos);
					Vector3 defPos = Vector3.zero;
					int deg = 0;
					pViewSystem.GetDefaultPokePos(vpos, ref defPos, ref deg, macro.place);
					pos.x = defPos.x;
					pos.y = ofsY + defPos.y - nodePos.y;
					if (pos.y <= 0.0f)
						pos.y = 0.0f;
					pos.z = defPos.z;
					pokeModel.SetTranslationVec(pos);
				}

				TaskPokeLandingMotion task = new TaskPokeLandingMotion(pViewSystem, vpos, pokeModel, pos.y, macro.place);
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManager().RegisterTask(task, true);
			}
		}
