				Vector3 pos = new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f);
				int frame = CALC_FRAME(param);
				BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, 0);
				BtlvPos vposSub = pViewSystem.SeqComFunc_GetTargetPokeSub(macro.trg);
				if (macro.isFlip && pViewSystem.SeqComFunc_IsFlipEffect(vpos, vposSub))
					pos.x = -macro.pos.x; // shipped: the raw macro value, not the scaled pos.x (0177aeec)

				BtlvPos trgPos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, 0);
				if (trgPos == BtlvPos.BTL_VPOS_ERROR)
					return;

				iPtrPoke = pViewSystem.GetPokeModel(trgPos);
				if (iPtrPoke == null)
					return;

				if (macro.relative)
					pos = iPtrPoke.GetTranslationVec() + pos;

				pos = pos + SceneObjectManager.Instance.StageModelPosition;
				if (frame == 0)
				{
					iPtrPoke.SetTranslationVec(pos);
					return;
				}

				TaskVectorControl task = new TaskVectorControl(iPtrPoke.GetTranslationVec(), pos, ((EaseFunc)macro.move).GetEase(), frame, x => iPtrPoke.SetTranslationVec(x));
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManager().RegisterTask(task, true);
			}
		}
		private void CNT_SEQ_FUNC_DEF_PokemonRotate(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ContestPokemonRotate macro)
			{
				BOPokemon iPtrPoke;
				int frame = CALC_FRAME(param);
				BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, 0);
				if (vpos == BtlvPos.BTL_VPOS_ERROR)
					return;

				BtlvPos vposSub = pViewSystem.SeqComFunc_GetTargetPokeSub(macro.trg);
				iPtrPoke = pViewSystem.GetPokeModel(vpos);

				Vector3 rot;
				rot.x = macro.scale.x;
				rot.y = -macro.scale.y;
				rot.z = macro.scale.z;
				if (macro.relative)
				{
					if (macro.isFlip & pViewSystem.SeqComFunc_IsFlipEffect(vpos, vposSub)) // non-short-circuit: the flip test always runs (0177b4e8-0177b55c)
					{
						rot.x = -rot.x;
						rot.y = -rot.y;
						rot.z = -rot.z;
					}

					rot = rot + iPtrPoke.GetRotationVec();
				}

				if (frame == 0)
				{
					iPtrPoke.SetRotationVec(rot);
					return;
				}

				TaskVectorControl task = new TaskVectorControl(iPtrPoke.GetRotationVec(), rot, ((EaseFunc)macro.move).GetEase(), frame, x => iPtrPoke.SetRotationVec(x));
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManager().RegisterTask(task, true);
			}
		}
		private void CNT_SEQ_FUNC_DEF_PokemonScale(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ContestPokemonScale macro)
			{
				BOPokemon iPtrPoke;
				int frame = CALC_FRAME(param);
				BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, 0);
				if (vpos == BtlvPos.BTL_VPOS_ERROR)
					return;

				iPtrPoke = pViewSystem.GetPokeModel(vpos);
				if (iPtrPoke == null)
					return;

				Vector3 scale = macro.scale;
				if (macro.relative)
				{
					Vector3 nowScale = iPtrPoke.GetScaleVec();
					scale = new Vector3(scale.x * nowScale.x, scale.y * nowScale.y, scale.z * nowScale.z);
				}

				if (frame == 0)
				{
					iPtrPoke.SetScaleVec(scale);
					return;
				}

				TaskVectorControl task = new TaskVectorControl(iPtrPoke.GetScaleVec(), scale, ((EaseFunc)macro.move).GetEase(), frame, x =>
				{
					if (iPtrPoke != null)
						iPtrPoke.SetScaleVec(x);
				});
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManager().RegisterTask(task, true);
			}
		}
		private void CNT_SEQ_FUNC_DEF_PokemonSpMoveShake(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ContestPokemonSpMoveShake macro)
			{
				BOPokemon iPtrPoke;
				int frame = CALC_FRAME(param);
				BtlvPos vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, 0);
				BtlvPos vposSub = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, 0);
				if (macro.isFlip && pViewSystem.SeqComFunc_IsFlipEffect(vpos, vposSub))
				{
					if (macro.axis == SEQ_DEF_AXIS.SEQ_DEF_AXIS_X_ROT || macro.axis == SEQ_DEF_AXIS.SEQ_DEF_AXIS_X)
					{
						// shipped: writes back into the macro itself (0177bda0-0177bdb0)
						macro.sdec += 0.5f;
						macro.edec += 0.5f;
					}
				}

				BtlvPos trgPos = pViewSystem.SeqComFunc_GetTargetPoke(macro.trg, 0);
				if (trgPos == BtlvPos.BTL_VPOS_ERROR)
					return;

				iPtrPoke = pViewSystem.GetPokeModel(trgPos);
				TaskShakeObject task = new TaskShakeObject(x => iPtrPoke.SetTranslationOffset(x), () => iPtrPoke.GetTranslationOffset(), () => iPtrPoke.GetRotationVec(), macro.srate, macro.erate, macro.sdec, macro.edec, frame, macro.axis);
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManager().RegisterTask(task, true);
			}
		}
		private void CNT_SEQ_FUNC_DEF_ModelCreateBall(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ContestModelCreateBall macro)
			{
				int frame = CALC_FRAME(param);
				ObjectEntity ballEntity = SceneObjectManager.Instance.GetBallObjEntityByPosID((int)macro.trgChara);
				ExtensionMethods.SetActive(ballEntity, true);
				if (!_uPtrModelHash.HasVector(param.GroupNo))
				{
					HashSet<ObjectEntity> models = new HashSet<ObjectEntity>();
					models.Add(ballEntity);
					_uPtrModelHash.CreateVector(param.GroupNo, models);
				}

				if (frame > 0)
				{
					TaskModelDelete task = new TaskModelDelete(ballEntity.gameObject, () => _uPtrModelHash.DeleteVector(param.GroupNo), frame);
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(task, true);
				}
			}
		}
		private void CNT_SEQ_FUNC_DEF_ContestModelAttachTrainer(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ContestModelAttachTrainer macro)
			{
				HashSet<ObjectEntity> models;
				if (!_uPtrModelHash.TryGetVector(param.GroupNo, out models))
					return;

				foreach (ObjectEntity model in models)
				{
					if (model == null)
						continue;

					BOTrainer trainer = pViewSystem.SeqComFunc_GetTargetChara(macro.trg, 0) as BOTrainer;
					if (!trainer)
						continue;

					if (macro.isEnable)
					{
						AContestPlayerData playerData = SceneObjectManager.Instance.GetPlayerDataByPosID((BtlvPos)macro.trg);
						JointName jointName = GetJointName((JointName)macro.node, playerData.playerInfo.trainerType);
						// shipped: macro.ignoreDominantHand / changeLight are never read; literal flags (0177c4a8-0177c4c4)
						trainer.AttachObject(model, jointName, true, false, true, true, true, macro.isAnimScl, macro.isLocalScl);
					}
					else
					{
						trainer.DetachObject(model);
					}
				}
			}
		}
		private global::Dpr.Battle.View.JointName GetJointName(global::Dpr.Battle.View.JointName jointName, global::XLSXContent.TrainerTable.SheetTrainerType trainerType) {
			switch (jointName)
			{
				case JointName.LItem1:
				case JointName.RItem1:
					return trainerType.Hand == Dpr.Trainer.HandDominance.L ? JointName.LItem1 : JointName.RItem1;
				case JointName.LItem2:
				case JointName.RItem2:
					return trainerType.Hand == Dpr.Trainer.HandDominance.L ? JointName.LItem2 : JointName.RItem2;
				default:
					return jointName;
			}
		}
		private void CNT_SEQ_FUNC_DEF_ContestModelAnimationPlayIndex(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ContestDprModelAnimationPlayIndex macro)
			{
				int frame = CALC_FRAME(param);
				HashSet<ObjectEntity> models;
				if (!_uPtrModelHash.TryGetVector(param.GroupNo, out models))
					return;

				foreach (ObjectEntity model in models)
				{
					ObjectEntity iPtrEntity;
					if (model == null)
						continue;

					iPtrEntity = model.GetComponent<ObjectEntity>();
					if (iPtrEntity == null)
						continue;

					iPtrEntity.Play(macro.index, macro.duration, macro.startTime, macro.isLoop);
					if (frame > 0)
					{
						TaskFinishFuncCall task = new TaskFinishFuncCall(frame, () => iPtrEntity.Stop());
						task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
						pViewSystem.GetTaskManager().RegisterTask(task, true);
					}
				}
			}
		}
