					if (frame == 0)
					{
						iPtrObj.SetScaleVec(scale);
						continue;
					}

					TaskVectorControl task = new TaskVectorControl(iPtrObj.GetScaleVec(), scale, ((EaseFunc)macro.move).GetEase(), frame, x => iPtrObj.SetScaleVec(x));
					task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
					pViewSystem.GetTaskManager().RegisterTask(task, true);
				}
			}
		}
