		private void OpenMsgWindow(global::Dpr.Message.MessageTextParseDataModel dataModel) {
			if (dataModel == null)
				return;

			Dpr.MsgWindow.MsgWindowParam msgWindowParam = new Dpr.MsgWindow.MsgWindowParam();
			msgWindowParam.textDataModel = dataModel;
			msgWindowParam.inputEnabled = false;
			msgWindowParam.forceSetMsgSpeed = ContestWork.sceneMsgSpeed;
			if (Dpr.MsgWindow.MsgWindowManager.IsOpen)
				Dpr.MsgWindow.MsgWindowManager.ReplaceBtlMsg(msgWindowParam);
			else
				Dpr.MsgWindow.MsgWindowManager.OpenBtlMsg(msgWindowParam);
		}
