		private void CNT_SEQ_FUNC_DEF_CameraMoveRelativePoke(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ContestCameraMoveRelativePoke macro)
			{
				int frame = CALC_FRAME(param);
				RELARIVE_POKE_OPTION opt = RELARIVE_POKE_OPTION.Factory();
				opt.m_node = macro.node;
				opt.m_rate = macro.rate;
				opt.m_adjustFlip = macro.isFlip;
				opt.m_adjustScale = macro.isScale;
				opt.m_autoRotateModel = false;
				opt.m_autoRotatePos = macro.isRot;
				opt.m_forceUpdate = macro.forceUpdate;

				SequenceCameraObject camera = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
				opt.m_vpos = pViewSystem.SeqComFunc_GetTargetPoke(macro.poke, 0);
				opt.m_vposSub = pViewSystem.SeqComFunc_GetTargetPokeSub(macro.poke);

				Vector3 pos = Vector3.zero;
				Vector3 trg = Vector3.zero;
				Vector3 rot = Vector3.zero;
				Vector3 scale = Vector3.zero;
				Vector3 ofs = Vector3.zero; // never used (fifth Vector3.zero call @0177da50, result discarded)

				opt.m_offset = new Vector3(macro.pos.x * -0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f);
				opt.ClearOtherElem(macro.enableElemPos);
				pViewSystem.SeqComFunc_GetPokeRelativePos(ref opt, ref pos, ref rot, ref scale, true);
				// elements disabled in m_targetElem keep the camera's current position (0177db30-0177db90)
				Vector3 camPos = camera.RawPosition;
				SetVectorSelectElem(ref camPos, ref pos, opt.m_targetElem);
				pos = camPos;

				opt.m_offset = new Vector3(macro.trg.x * -0.01f, macro.trg.y * 0.01f, macro.trg.z * 0.01f);
				opt.ClearOtherElem(macro.enableElemTrg);
				pViewSystem.SeqComFunc_GetPokeRelativePos(ref opt, ref trg, ref rot, ref scale, true);
				Vector3 camTrg = camera.GetTarget();
				SetVectorSelectElem(ref camTrg, ref trg, opt.m_targetElem);
				trg = camTrg;

				if (opt.m_rate != DEFAULT_MOVE_RATE)
				{
					Vector3 nowPos = camera.RawPosition;
					Vector3 nowTrg = camera.GetTarget();
					pos = nowPos + (pos - nowPos) * (opt.m_rate * 0.01f);
					trg = nowTrg + (trg - nowTrg) * (opt.m_rate * 0.01f);
				}

				if (frame == 0)
				{
					camera.SetPosition(pos, trg);
					if (!Mathf.Approximately(macro.fov, 0.0f))
						camera.Fov = macro.fov;
					return;
				}

				TaskCameraMove task = new TaskCameraMove(camera, pos, trg, macro.fov, ((EaseFunc)macro.move).GetEase(), frame);
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManagerLate().RegisterTask(task, true);
			}
		}
		private void CNT_SEQ_FUNC_DEF_CameraMoveRelativeStage(global::Dpr.SequenceEditor.SequenceFile pSeqFile, global::Dpr.SequenceEditor.ISequenceViewSystem pViewSystem, global::Dpr.SequenceEditor.CommandParam param) {
			if (param.Macro is ContestCameraMoveRelativeStage macro)
			{
				int frame = CALC_FRAME(param);
				SequenceCameraObject camera = GetCameraSystem().GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
				Vector3 pos = new Vector3(macro.pos.x * 0.01f, macro.pos.y * 0.01f, macro.pos.z * 0.01f);
				if (macro.relative)
					pos = pos + camera.GetPosition();

				if (pViewSystem is ContestViewSystem viewSystem && viewSystem.SystemType == ContestViewSystem.ViewSystemType.Waza)
					pos = pos + SceneObjectManager.Instance.StageModelPosition;

				Vector3 camPos = camera.GetPosition();
				SetVectorSelectElem(ref camPos, ref pos, macro.enableElemPos);
				if (frame == 0)
				{
					camera.SetPosition(pos); // shipped: the unselected pos, camPos is only used by the task (0177e408)
					return;
				}

				// shipped: macro.trg, macro.fov and enableElemTrg are never read
				TaskCameraMove task = new TaskCameraMove(camera, camPos, ((EaseFunc)macro.move).GetEase(), frame);
				task.SetStartTime(param.StartTime).SetEndTime(param.EndTime).SetAdvanceMode(Task.AdvanceMode.Time);
				pViewSystem.GetTaskManagerLate().RegisterTask(task, true);
			}
		}
